import type { ScorecardV3Field } from "./createScorecardV3Script";

/**
 * Default priority-ordered list of label substrings used to identify the
 * "general notes" (overall summary) field across ATS adapters. The first
 * field whose `text` (case-insensitive substring) matches an alias here
 * wins; if no field matches, callers should fall back to the first
 * fillable field.
 *
 * Order matters — earlier aliases take priority. "Additional feedback"
 * comes first because Ashby and Workday's questionnaire pages render a
 * dedicated bottom-of-form textarea with that label, which is the
 * conventionally correct target.
 */
export const GENERAL_NOTES_LABEL_ALIASES: readonly string[] = [
  "additional feedback",
  "overall comment",
  "key takeaways",
];

/**
 * Pick a "general notes" field from a list of scraped scorecard fields.
 *
 * Matching strategy:
 *   1. For each alias in `labelAliases` (in order), return the first
 *      field whose `text` (case-insensitive substring) matches.
 *   2. Otherwise fall back to the first field with a non-null editor.
 *   3. Return `null` only when no field has a fillable editor.
 *
 * The default alias list is `GENERAL_NOTES_LABEL_ALIASES`. Pass an
 * explicit list to override (e.g. an ATS that should never match a
 * particular alias). Pass `[]` to skip label matching entirely and
 * always return the first fillable field — useful for ATSes like Lever
 * that have no dedicated "overall" field convention.
 */
export const pickGeneralNotesField = (
  fields: readonly ScorecardV3Field[],
  labelAliases: readonly string[] = GENERAL_NOTES_LABEL_ALIASES,
): ScorecardV3Field | null => {
  for (const alias of labelAliases) {
    const lc = alias.toLowerCase();
    const hit = fields.find(
      (f) => f.editor && f.text.toLowerCase().includes(lc),
    );
    if (hit) return hit;
  }
  return fields.find((f) => f.editor) ?? null;
};
