import confetti from "canvas-confetti";

export function showConfetti(): void {
  const offset = 15;

  const randY = (min = 0.3, max = 0.7): number => {
    return Math.random() * (max - min) + min;
  };

  const baseOpts = {
    disableForReducedMotion: true,
    colors: ["#0772D0", "#0074dd"],
    spread: 120,
    particleCount: 80,
  };

  const timeout = (ms: number): Promise<void> =>
    new Promise((resolve) => setTimeout(resolve, ms));

  async function run(): Promise<void> {
    confetti({
      ...baseOpts,
      origin: { x: 0.2, y: randY() },
      angle: 90 - offset,
    });

    await timeout(150);
    confetti({
      ...baseOpts,
      origin: { x: 0.5, y: randY() },
      angle: 90,
    });

    await timeout(150);
    confetti({
      ...baseOpts,
      origin: { x: 0.8, y: randY() },
      angle: 90 + offset,
    });
  }

  setTimeout(() => {
    run();
  }, 350);
}
