import { SquareArrowOutUpRight } from "lucide-static";

import { createAutofillOptionsSection } from "./autofillOptions";
import {
  clockIcon,
  interviewQuestionsIcon,
  sparkleIcon,
  warningIconLarge,
} from "./icons";
import { createSVGFromString } from "./utils";

const AUTO_FILL_BUTTON_ID = "bh-autofill-btn";
const CONFIRM_MODAL_ID = "bh-confirm-autofill-modal";

type ConfirmAutofillModalOptions = {
  onConfirm: () => void;
  onCancel: () => void;
};

/**
 * Creates a confirmation modal shown when a user tries to autofill a
 * scorecard that has already been autofilled (via auto-draft or a previous
 * manual autofill).
 */
export const createConfirmAutofillModal = ({
  onConfirm,
  onCancel,
}: ConfirmAutofillModalOptions): HTMLElement => {
  // Remove any existing modal
  document.getElementById(CONFIRM_MODAL_ID)?.remove();

  const overlay = document.createElement("div");
  overlay.id = CONFIRM_MODAL_ID;
  overlay.className = "bh-confirm-modal-overlay";

  const dialog = document.createElement("div");
  dialog.className = "bh-confirm-modal";
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-labelledby", "bh-confirm-modal-title");
  dialog.setAttribute("aria-describedby", "bh-confirm-modal-body");

  const title = document.createElement("h2");
  title.id = "bh-confirm-modal-title";
  title.className = "bh-confirm-modal__title";
  title.textContent = "Scorecard already filled with these settings";
  dialog.appendChild(title);

  const body = document.createElement("p");
  body.id = "bh-confirm-modal-body";
  body.className = "bh-confirm-modal__body";
  body.textContent =
    "Your scorecard has already been autofilled. Autofilling again will add responses beneath any existing content in each question field, and much of it may be similar to what was already generated.";
  dialog.appendChild(body);

  const footer = document.createElement("div");
  footer.className = "bh-confirm-modal__footer";

  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "bh-confirm-modal__btn bh-confirm-modal__btn--cancel";
  cancelBtn.textContent = "Cancel";
  cancelBtn.addEventListener("click", () => {
    overlay.remove();
    onCancel();
  });
  footer.appendChild(cancelBtn);

  const confirmBtn = document.createElement("button");
  confirmBtn.type = "button";
  confirmBtn.className = "bh-confirm-modal__btn bh-confirm-modal__btn--confirm";
  confirmBtn.textContent = "Autofill again";
  confirmBtn.addEventListener("click", () => {
    overlay.remove();
    onConfirm();
  });
  footer.appendChild(confirmBtn);

  dialog.appendChild(footer);
  overlay.appendChild(dialog);

  // Close on overlay click
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) {
      overlay.remove();
      onCancel();
    }
  });

  return overlay;
};

const createInterviewDataFields = (
  interviewData: FillScorecardV3CallDetails | null,
): HTMLElement => {
  const container = document.createElement("div");
  container.className = "bh-interview-data-fields";

  const fields = [
    { label: "Date", value: interviewData?.date || "" },
    { label: "Candidate", value: interviewData?.candidate || "" },
    { label: "Interview", value: interviewData?.interview || "" },
    { label: "Duration", value: interviewData?.duration || "" },
    {
      label: "Interviewers",
      value: interviewData?.interviewers?.join(", ") || "",
    },
  ];

  fields.forEach((field) => {
    const fieldEl = document.createElement("div");
    fieldEl.className = "bh-interview-field";

    const labelEl = document.createElement("div");
    labelEl.className = "bh-interview-field__label";
    labelEl.textContent = field.label;

    const valueEl = document.createElement("div");
    valueEl.className = "bh-interview-field__value";
    valueEl.textContent = field.value || "-";

    fieldEl.appendChild(labelEl);
    fieldEl.appendChild(valueEl);
    container.appendChild(fieldEl);
  });

  return container;
};

const createBodyDisplayMessage = (params: {
  header: string;
  subText: string;
  icon: string;
}): HTMLElement => {
  const container = document.createElement("div");
  container.className = "bh-no-call-selected-state";

  // Icon
  const iconEl = createSVGFromString(params.icon);
  iconEl.setAttribute("class", "bh-no-call-selected-icon");
  container.appendChild(iconEl);

  // Text container
  const textContainer = document.createElement("div");
  textContainer.className = "bh-no-call-selected-text";

  const line1 = document.createElement("div");
  line1.className = "bh-no-call-selected-text__line bh-text-primary";
  line1.textContent = params.header;
  textContainer.appendChild(line1);

  const line2 = document.createElement("div");
  line2.className = "bh-no-call-selected-text__line";
  line2.textContent = params.subText;
  textContainer.appendChild(line2);

  container.appendChild(textContainer);

  return container;
};

const createNoCallSelectedState = (params: {
  onSelectInterview: () => void;
}): HTMLElement => {
  const { onSelectInterview } = params;
  const container = createBodyDisplayMessage({
    header:
      "We were not able to automatically choose the recording for this scorecard.",
    subText: "Please select a recording to autofill this scorecard.",
    icon: interviewQuestionsIcon,
  });

  // Select interview button
  const selectInterviewBtn = document.createElement("button");
  selectInterviewBtn.type = "button";
  selectInterviewBtn.className = "bh-select-interview-button";
  selectInterviewBtn.textContent = "Select interview";
  selectInterviewBtn.addEventListener("click", () => {
    onSelectInterview();
  });
  container.appendChild(selectInterviewBtn);

  return container;
};

type CreateScorecardUIOptions = {
  loading?: boolean;
  autofillInProgress?: boolean;
  autofillDisabled?: boolean;
  showButtonShine?: boolean;
  interviewData: FillScorecardV3CallDetails | null;
  autofillOptions: AutofillOptions;
  summaryTemplates: AutofillSummaryTemplate[];
  /**
   * When true, the "Autofill options" row (including the "Include additional
   * summary" toggle) is hidden. Used when the V3 UI is shown in legacy mode
   * — i.e. the `autofill-scorecard:v3` flag is off and the V2 notes pipeline
   * is used instead of the AI mutation.
   */
  legacyMode?: boolean;
  getTooltipText?: (hasCustomTemplates: boolean) => string;
  learnMoreUrl?: string;
  forceNarrowLayout?: boolean;
  onImportAll: (e: MouseEvent) => void;
  onSelectInterview: () => void;
  onAutofillOptionsChange: (options: AutofillOptions) => void;
};

const createAutofillButton = (params: {
  onClick: (e: MouseEvent) => void;
  disabled?: boolean;
  isLoading?: boolean;
  shine?: boolean;
}): HTMLButtonElement => {
  const button = document.createElement("button");
  button.type = "button";
  button.disabled = params.disabled ?? false;
  button.onclick = params.onClick;

  const icon = createSVGFromString(sparkleIcon);
  button.appendChild(icon);

  const textEl = document.createElement("span");
  textEl.textContent = "Autofill scorecard";
  button.appendChild(textEl);

  if (params.isLoading) {
    button.classList.add("bh-loading");
    icon.classList.add("bh-sparkle-animated");
    textEl.textContent = "Filling scorecard";
    textEl.style.marginRight = "5.5px";
    button.onclick = null;
  }

  if (params.shine && !(params.disabled || params.isLoading)) {
    button.classList.add("bh-shine");
  }

  return button;
};

/**
 * Creates the main scorecard UI component
 */
export const createScorecardUI = ({
  loading,
  autofillInProgress,
  autofillDisabled,
  showButtonShine,
  interviewData,
  autofillOptions,
  summaryTemplates,
  legacyMode,
  getTooltipText,
  learnMoreUrl,
  forceNarrowLayout,
  onImportAll,
  onSelectInterview,
  onAutofillOptionsChange,
}: CreateScorecardUIOptions): HTMLElement => {
  const container = document.createElement("div");
  container.className =
    forceNarrowLayout || legacyMode
      ? "bh-scorecard-ui bh-scorecard-ui--narrow-layout"
      : "bh-scorecard-ui";

  // Header section
  const header = document.createElement("div");
  header.className = "bh-scorecard-ui__header";

  // First row: Logo + Title + Button
  const headerRow1 = document.createElement("div");
  headerRow1.className = "bh-scorecard-ui__header-row";

  // Left side: Logo + Title
  const leftSection = document.createElement("div");
  leftSection.className = "bh-scorecard-ui__header-left";
  const logo = document.createElement("img");
  logo.src = "https://app.brighthire.ai/static/images/logo_ui.svg";
  logo.alt = "BrightHire";
  logo.style.width = "24px";
  logo.style.height = "24px";
  leftSection.appendChild(logo);

  const title = document.createElement("span");
  title.className = "bh-scorecard-ui__title";
  title.textContent = "BrightHire Scorecard Autofill";
  leftSection.appendChild(title);

  if (learnMoreUrl) {
    const learnMore = document.createElement("a");
    learnMore.className = "bh-scorecard-ui__learn-more";
    learnMore.href = learnMoreUrl;
    learnMore.target = "_blank";
    learnMore.rel = "noopener noreferrer";

    learnMore.appendChild(document.createTextNode("Learn more"));

    const learnMoreLong = document.createElement("span");
    learnMoreLong.className = "bh-scorecard-ui__learn-more-long";
    learnMoreLong.textContent = "about the updated Scorecard Autofill";
    learnMore.appendChild(learnMoreLong);

    const icon = createSVGFromString(SquareArrowOutUpRight);
    learnMore.appendChild(icon);

    headerRow1.appendChild(leftSection);
    headerRow1.appendChild(learnMore);
  } else {
    headerRow1.appendChild(leftSection);
  }

  header.appendChild(headerRow1);

  // Second row: Autofill options — hidden in legacy mode
  const buttonParams = {
    isLoading: autofillInProgress,
    disabled: autofillDisabled,
    shine: showButtonShine,
    onClick: (e: MouseEvent) => {
      onImportAll(e);
    },
  };

  // Remove any previously rendered buttons before creating new ones
  document
    .querySelectorAll(`#${AUTO_FILL_BUTTON_ID}, .bh-autofill-btn--stacked`)
    .forEach((el) => {
      el.remove();
    });

  // Inline button: shown at wider widths, sits beside the autofill row
  const autofillButtonInline = createAutofillButton(buttonParams);
  autofillButtonInline.id = AUTO_FILL_BUTTON_ID;
  autofillButtonInline.classList.add("bh-autofill-btn--inline");

  // Stacked button: shown at narrow widths, sits below the autofill row
  const autofillButtonStacked = createAutofillButton(buttonParams);
  autofillButtonStacked.classList.add("bh-autofill-btn--stacked");

  if (!legacyMode) {
    const autofillRow = document.createElement("div");
    autofillRow.className = "bh-scorecard-ui__autofill-row";

    const autofillOptionsSection = createAutofillOptionsSection({
      templates: summaryTemplates,
      includeAdditionalSummary: autofillOptions.includeAdditionalSummary,
      selectedTemplateId: autofillOptions.selectedTemplateId ?? null,
      selectedStyle: autofillOptions.overallSummaryStyle,
      selectedDetailLevel: autofillOptions.detailLevel ?? "MEDIUM",
      isAiInterview: !!interviewData?.isAiInterview,
      getTooltipText,
      onIncludeAdditionalSummaryChange: (checked) => {
        onAutofillOptionsChange({
          ...autofillOptions,
          includeAdditionalSummary: checked,
        });
      },
      onTemplateSelect: (template) => {
        onAutofillOptionsChange({
          ...autofillOptions,
          selectedTemplateId: template.id ?? null,
          overallSummaryStyle: template.overallSummaryStyle ?? null,
        });
      },
      onDetailLevelChange: (detailLevel) => {
        onAutofillOptionsChange({
          ...autofillOptions,
          detailLevel,
        });
      },
      disabled: autofillDisabled || autofillInProgress,
    });

    autofillRow.appendChild(autofillOptionsSection);
    if (!forceNarrowLayout) {
      autofillRow.appendChild(autofillButtonInline);
    }

    if (interviewData !== null) {
      header.appendChild(autofillRow);
    }
  }

  container.appendChild(header);

  // Body section
  const body = document.createElement("div");
  body.className = "bh-scorecard-ui__body";

  if (loading) {
    const loadingSpinner = document.createElement("div");
    loadingSpinner.className = "bh-loading-spinner";
    body.appendChild(loadingSpinner);
  } else if (interviewData === null) {
    const noCallState = createNoCallSelectedState({
      onSelectInterview,
    });
    body.appendChild(noCallState);
  } else {
    const bodyHeader = document.createElement("div");
    bodyHeader.className = "bh-scorecard-ui__body-header";

    const matchedLabel = document.createElement("span");
    matchedLabel.className = "bh-matched-interview-label";
    matchedLabel.textContent = "Matched interview";
    bodyHeader.appendChild(matchedLabel);

    const changeInterviewBtn = document.createElement("button");
    changeInterviewBtn.type = "button";
    changeInterviewBtn.className = "bh-change-interview-button";
    changeInterviewBtn.textContent = "Change interview";
    changeInterviewBtn.addEventListener("click", () => {
      onSelectInterview();
    });
    bodyHeader.appendChild(changeInterviewBtn);
    body.appendChild(bodyHeader);

    if (interviewData.transcriptLoading) {
      const notesNotReadyState = createBodyDisplayMessage({
        header: "We're still processing this interview.",
        subText:
          "Autofill will be available when we finish transcribing the recording. Check back soon.",
        icon: clockIcon,
      });
      body.appendChild(notesNotReadyState);
    } else if (interviewData.autofillUnavailable) {
      const unavailableState = createBodyDisplayMessage({
        header: "Scorecard autofill unavailable",
        subText:
          "Scorecard autofill requires AI notes, which weren't generated for this conversation. Please contact support if you believe this is an error.",
        icon: warningIconLarge,
      });
      body.appendChild(unavailableState);
    } else {
      const interviewFields = createInterviewDataFields(interviewData);
      body.appendChild(interviewFields);
    }
  }

  container.appendChild(body);
  if (interviewData !== null) {
    container.appendChild(autofillButtonStacked);
  }

  return container;
};
