// cspell:ignore trix
import { setupDrawer } from "../../utils/drawer";
import {
  featureFlagEnabled,
  getWorkdayQuestionnaireTitles,
} from "../../utils/featureFlag";
import { sendMessageWithTabId } from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { transformText } from "../../utils/string";
import { getUiConfig } from "../../utils/ui-config";
import { FALLBACK_CONFIG } from "../../utils/ui-config/UI_CONFIG";
import {
  createScorecardV3Script,
  type ScorecardV3Field,
} from "../one-click-scorecard/v3/createScorecardV3Script";
import {
  GENERAL_NOTES_LABEL_ALIASES,
  pickGeneralNotesField,
} from "../one-click-scorecard/v3/generalNotesField";
import {
  renderBulletsToPlainText,
  renderMarkdownToPlainText,
  renderSummarySectionsToPlainText,
} from "../one-click-scorecard/v3/structuredNoteRenderers";

let SELECTORS = FALLBACK_CONFIG["workday.rateInterview"];

type Page =
  | "giveFeedbackTask"
  | "rateInterviewTask"
  | "questionnaireTask"
  | null;

// Cache for the current page type to avoid repeated async checks
let cachedPageType: Page = null;

const matchesDocumentTitle = (): boolean =>
  !!SELECTORS.documentTitleRegex.some((re) =>
    document.title.match(new RegExp(re, "i")),
  );

const isRateInterviewTaskPage = (): boolean => {
  return (
    !!document.querySelector(SELECTORS.rateInterviewTitleEl.join(",")) &&
    !!document.querySelector(SELECTORS.hiringTeamCommentTextEl.join(","))
  );
};

// Page-header titles where the user can actually edit / submit interview
// feedback. The fallback "Interview Feedback" heading also shows up on
// read-only / management pages (e.g. "Manage Interview Feedback") that the
// recruiter/HM uses to review pending submissions — we must NOT render the
// autofill UI there.
const EDITABLE_FEEDBACK_HEADER_REGEXES = [
  /^give interview feedback/i,
  /^rate interview/i,
];

const hasEditableFeedbackPageHeader = (): boolean => {
  const headerText =
    document
      .querySelector<HTMLElement>(SELECTORS.inboxItemTitleEl.join(","))
      ?.textContent?.trim() ?? "";
  if (!headerText) return false;
  return EDITABLE_FEEDBACK_HEADER_REGEXES.some((re) => re.test(headerText));
};

// At least one editable scorecard textarea inside the Interview Feedback
// section. Read-only review pages (e.g. "Manage Interview Feedback") render
// the same `[title="Interview Feedback"]` heading but only show interviewer
// statuses + a read-only text view — no editable per-question textareas.
const hasEditableScorecardTextarea = (): boolean => {
  const feedbackEl = document.querySelector<HTMLElement>(
    SELECTORS.interviewFeedbackTitleEl,
  );
  const feedbackAncestor = feedbackEl?.closest<HTMLElement>(
    SELECTORS.giveFeedbackCommonAncestor.join(","),
  );
  if (!feedbackAncestor) return false;
  return !!feedbackAncestor.querySelector<HTMLTextAreaElement>(
    SELECTORS.getTextArea.join(","),
  );
};

const isGiveFeedbackTaskPage = (): boolean => {
  // Primary: look for the "Overall Feedback" section heading. This is the
  // strongest positive signal — only the editable feedback task page has it.
  if (document.querySelector(SELECTORS.giveFeedbackTitleEl.join(","))) {
    return true;
  }
  // Fallback: Workday can be configured to hide Overall Feedback fields.
  // When that happens, detect the page via the "Interview Feedback" heading.
  // The heading alone is not enough — "Manage Interview Feedback" (a
  // read-only review page accessible to certain managers) has the same
  // heading, so additionally require:
  //   1. the page-header title is an editable feedback task ("Give Interview
  //      Feedback" / "Rate Interview"), and
  //   2. at least one editable scorecard textarea inside the section.
  if (!document.querySelector(SELECTORS.interviewFeedbackTitleEl)) {
    return false;
  }
  return hasEditableFeedbackPageHeader() && hasEditableScorecardTextarea();
};

const isValidQuestionnairePage = async (): Promise<boolean> => {
  const el = document.querySelector(SELECTORS.inboxItemTitleEl.join(","));
  const titles = await getWorkdayQuestionnaireTitles();
  if (!titles || !el?.innerHTML) return false;
  if (titles.includes(el?.innerHTML)) {
    return true;
  }
  return false;
};

const setupCloseButtons = (retries = 0): void => {
  /** Retry for up to 15 seconds until DOM elements are available */
  const closeButtons = Array.from(
    document.querySelectorAll<HTMLButtonElement>(
      '[data-automation-id="closeButton"]',
    ),
  );
  console.log("CLOSE BUTTONS", closeButtons);
  if (retries < 50 && closeButtons.length === 0) {
    setTimeout(() => setupCloseButtons(retries + 1), 300);
    return;
  }
  closeButtons.forEach((closeButton) => {
    closeButton.addEventListener("click", async () => {
      const loading = await setupDrawer();
      if (loading) sendMessageWithTabId({ action: "drawerLoading" });
    });
  });
};

const getPageType = async (): Promise<Page> => {
  let _pageType: Page = null;
  if (!matchesDocumentTitle()) {
    if (await isValidQuestionnairePage()) {
      _pageType = "questionnaireTask";
    }
  }
  if (isGiveFeedbackTaskPage()) _pageType = "giveFeedbackTask";
  if (isRateInterviewTaskPage()) _pageType = "rateInterviewTask";
  if (await isValidQuestionnairePage()) _pageType = "questionnaireTask";
  if (_pageType) setupCloseButtons();
  return _pageType;
};

const updateCachedPageType = async (): Promise<Page> => {
  cachedPageType = await getPageType();
  return cachedPageType;
};

const getCompetencyFields = (root: HTMLElement): ScorecardV3Field[] => {
  // Modern Workday "Interview Feedback" layouts render each competency /
  // skill as its own panel (no surrounding `fieldSetContent`). The panel
  // contains: Competency name (textView), an optional rich-text description
  // (the behavioral definition), a Rating field, and a Comment textarea.
  //
  // We identify a competency row by a panel that contains BOTH a textarea
  // and a description (richTextContent). The textarea is the paste target;
  // the description is what we want the AI to see so it can write a
  // relevant comment for the skill.
  const competencyPanelSelector = SELECTORS.competencyPanel?.join(",");
  const competencyDescriptionSelector =
    SELECTORS.competencyDescription?.join(",");
  const competencyNameSelector = SELECTORS.competencyName?.join(",");

  if (
    !competencyPanelSelector ||
    !competencyDescriptionSelector ||
    !competencyNameSelector
  ) {
    return [];
  }

  const panels = Array.from(
    root.querySelectorAll<HTMLElement>(competencyPanelSelector),
  );

  // Track textareas we've already claimed so a parent panel doesn't pick up
  // a child panel's textarea.
  const claimedTextareas = new Set<HTMLTextAreaElement>();
  // De-dupe nested panels that share the same competency content.
  const seenKeys = new Set<string>();

  // Sort by depth so the deepest (most specific) panel wins.
  panels.sort((a, b) => getDepth(b) - getDepth(a));

  const fields: ScorecardV3Field[] = [];

  for (const panel of panels) {
    // Skip rows with rating radio groups (those are different field types
    // and not our paste target).
    if (panel.querySelector(SELECTORS.isRadioGroup.join(","))) continue;

    const textarea = panel.querySelector<HTMLTextAreaElement>(
      SELECTORS.getTextArea.join(","),
    );
    if (!textarea || textarea.tagName.toLowerCase() !== "textarea") continue;
    if (claimedTextareas.has(textarea)) continue;

    const description =
      panel
        .querySelector(competencyDescriptionSelector)
        ?.textContent?.replace(/\s+/g, " ")
        .trim() ?? "";
    // Without a description this isn't a competency row — let the fieldset
    // path handle it.
    if (!description) continue;

    const name =
      panel.querySelector(competencyNameSelector)?.textContent?.trim() ?? "";

    const text = name ? `${name}\n${description}` : description;
    const key = transformText(text);
    if (!key || seenKeys.has(key)) continue;
    seenKeys.add(key);
    claimedTextareas.add(textarea);

    fields.push({
      text,
      transformedText: key,
      editor: textarea as HTMLElement | null,
    });
  }

  return fields;
};

const getDepth = (el: HTMLElement): number => {
  let depth = 0;
  let cur: HTMLElement | null = el;
  while (cur) {
    depth += 1;
    cur = cur.parentElement;
  }
  return depth;
};

/**
 * When we detect a Workday scorecard / feedback / questionnaire page, signal
 * interview intent to the drawer so it routes to the interview landing page
 * instead of the candidate-alert ("Pick interview") page.
 *
 * The drawer script (workdayDrawerContentScript.ts) continues to set `intent: "Candidate"` for
 * non-feedback pages, and we override here when we know it's a feedback page.
 */
const signalInterviewIntentIfFeedbackPage = async (): Promise<void> => {
  const pageType = await updateCachedPageType();
  if (pageType === null) return;

  const reloadTriggered = await setupDrawer({
    urlParams: { intent: "Interview" },
    forceReload: true,
  });
  if (reloadTriggered) {
    sendMessageWithTabId({ action: "drawerLoading" });
  }
};

const getScorecardFields = async (): Promise<ScorecardV3Field[]> => {
  const pageType = await getPageType();

  // Resolve the root we walk for the legacy `fieldSetContent` pass. This
  // root is also the fallback for the competency pass on questionnaire
  // pages (whose competency panels live inside the same questionnaire
  // container, not a separate "Interview Feedback" section).
  let fieldsetRoot: HTMLElement | null | undefined = null;
  if (pageType === "questionnaireTask") {
    // TODO: make more robust
    fieldsetRoot = document.querySelector<HTMLElement>(
      SELECTORS.questionnaireTitleEl.join(","),
    )?.parentElement?.parentElement;
  } else {
    // The competency panels (and any other editable scorecard rows)
    // live in the separate "Interview Feedback" section handled below.
    fieldsetRoot =
      document
        .querySelector(SELECTORS.additionalQuestionsTitleEl)
        ?.closest<HTMLElement>(
          SELECTORS.giveFeedbackCommonAncestor.join(","),
        ) ?? null;
  }

  // Pull out any per-competency rows in the modern Workday layout. For
  // giveFeedbackTask / rateInterviewTask the competency panels live inside
  // the "Interview Feedback" section, not the optional "Additional
  // Questions" section. Use the wider feedback ancestor so we don't miss
  // them when "Additional Questions" is hidden in the tenant config.
  let competencyRoot: HTMLElement | null = null;
  if (pageType === "questionnaireTask") {
    competencyRoot = fieldsetRoot ?? null;
  } else {
    const interviewFeedbackEl = document.querySelector<HTMLElement>(
      SELECTORS.interviewFeedbackTitleEl,
    );
    const feedbackAncestor = interviewFeedbackEl?.closest<HTMLElement>(
      SELECTORS.giveFeedbackCommonAncestor.join(","),
    );
    competencyRoot = feedbackAncestor ?? fieldsetRoot ?? null;
  }
  const competencyFields = competencyRoot
    ? getCompetencyFields(competencyRoot)
    : [];

  // Then walk the legacy `fieldSetContent` rows (covers Additional Questions
  // and older Workday tenants where the description is embedded in the
  // fieldset legend itself). Skip when there's no Additional-Questions root
  // — competency-only tenants will have already populated `competencyFields`.
  if (!fieldsetRoot) {
    return competencyFields;
  }

  const claimedTextareas = new Set<HTMLElement | null>(
    competencyFields.map((f) => f.editor),
  );
  const questions = fieldsetRoot.querySelectorAll<HTMLElement>(
    SELECTORS.feedbackQuestionsSubEl,
  );

  const fieldsetFields = Array.from(questions)
    .map((q) => {
      // Skip fieldsets with radio button groups
      const hasRadioGroup = q.querySelector(SELECTORS.isRadioGroup.join(","));
      if (hasRadioGroup) {
        return null;
      }

      // Get the textarea element
      const textarea = q.querySelector<HTMLTextAreaElement>(
        SELECTORS.getTextArea.join(","),
      );

      if (textarea && textarea.tagName.toLowerCase() !== "textarea") {
        return null;
      }
      // Skip textareas already paired with a competency row above.
      if (textarea && claimedTextareas.has(textarea)) {
        return null;
      }

      // Get the text from the legend label
      const legendText =
        q
          .querySelector(SELECTORS.getQuestionText.join(","))
          ?.textContent?.trim() || "";

      return {
        text: legendText,
        transformedText: transformText(legendText),
        editor: textarea as HTMLElement | null,
      };
    })
    .filter((item): item is ScorecardV3Field => item !== null);

  return [...competencyFields, ...fieldsetFields];
};

/**
 * Workday-specific helper: scan all `[data-automation-id="formLabel"]`
 * widgets on the page for any of `labelAliases` (case-insensitive
 * substring), then resolve the associated `<textarea>` via Workday's two
 * conventions:
 *   1. `label[for]` → `document.getElementById(forId)`
 *   2. `label.closest('[role="presentation"]')` → `.querySelector(textarea)`
 *
 * Returns the first hit in alias priority order; nothing if no formLabel
 * on the page matches any alias.
 */
const findOverallTextareaByFormLabel = (): ScorecardV3Field | null => {
  const allFormLabels = document.querySelectorAll<HTMLElement>(
    '[data-automation-id="formLabel"]',
  );
  for (const alias of GENERAL_NOTES_LABEL_ALIASES) {
    const lc = alias.toLowerCase();
    for (const label of Array.from(allFormLabels)) {
      const labelText = label.textContent?.trim() ?? "";
      if (!labelText.toLowerCase().includes(lc)) continue;

      // The label's `for` attribute points to the textarea input id.
      const forId = label.getAttribute("for");
      if (forId) {
        const textarea = document.getElementById(
          forId,
        ) as HTMLTextAreaElement | null;
        if (textarea?.tagName.toLowerCase() === "textarea") {
          return {
            text: labelText,
            transformedText: transformText(labelText),
            editor: textarea,
          };
        }
      }
      // Also try finding a textarea as a sibling/cousin of the label.
      const container = label.closest('[role="presentation"]');
      if (container) {
        const textarea = container.querySelector<HTMLTextAreaElement>(
          SELECTORS.getTextArea.join(","),
        );
        if (textarea) {
          return {
            text: labelText,
            transformedText: transformText(labelText),
            editor: textarea,
          };
        }
      }
    }
  }
  return null;
};

const getGeneralNotesField = async (): Promise<ScorecardV3Field | null> => {
  const pageType = cachedPageType ?? (await getPageType());

  if (pageType === "questionnaireTask") {
    // The shared helper handles the full priority list (additional
    // feedback > overall comment > key takeaways > first fillable)
    // against the already-scraped per-question scorecard fields.
    return pickGeneralNotesField(await getScorecardFields());
  }

  // For giveFeedbackTask and rateInterviewTask pages

  // 1. Primary: find the textarea inside the "Overall Feedback" section.
  // This is Workday-specific — `[title="overall feedback"]` is a section
  // heading attribute, not a label-text match.
  const overallFeedbackTextarea =
    document
      .querySelector(SELECTORS.giveFeedbackTitleEl.join(","))
      ?.closest(SELECTORS.giveFeedbackCommonAncestor.join(","))
      ?.querySelector<HTMLTextAreaElement>("textarea") ?? null;

  if (overallFeedbackTextarea) {
    return {
      text: "",
      transformedText: "",
      editor: overallFeedbackTextarea,
    };
  }

  // 2. Fallback: Workday may hide the "Overall Feedback" section. Scan
  //    all formLabels on the page for any of the shared general-notes
  //    aliases ("additional feedback" > "overall comment" > "key
  //    takeaways"), resolving the textarea via Workday's `for=` and
  //    `role=presentation` conventions.
  const labeledMatch = findOverallTextareaByFormLabel();
  if (labeledMatch) return labeledMatch;

  // 3. Last resort: use the first textarea on the page (within the feedback form)
  const feedbackSection = document
    .querySelector(SELECTORS.interviewFeedbackTitleEl)
    ?.closest(SELECTORS.giveFeedbackCommonAncestor.join(","));
  if (feedbackSection) {
    const firstTextarea = feedbackSection.querySelector<HTMLTextAreaElement>(
      SELECTORS.getTextArea.join(","),
    );
    if (firstTextarea) {
      return {
        text: "",
        transformedText: "",
        editor: firstTextarea,
      };
    }
  }

  return null;
};

const getTooltipText = (hasCustomTemplates: boolean): string => {
  if (cachedPageType === "questionnaireTask") {
    return hasCustomTemplates
      ? 'Adds a summary to an "Additional feedback" text field if one exists, or to the first text field on the scorecard. Choose between your custom AI note template or BrightHire\'s default interview overview.'
      : 'Adds a summary of important interview topics not covered by your scorecard questions. BrightHire adds it to an "Additional feedback" text field if one exists, or to the first text field on the scorecard.';
  }
  // giveFeedbackTask / rateInterviewTask
  return hasCustomTemplates
    ? "Adds a summary to the Overall Comment section (or the first available text field) when you autofill. Choose between your custom template or BrightHire's default interview overview."
    : "Adds a summary of important interview topics not covered by your scorecard questions to the Overall Comment section, or the first available text field.";
};

const v3EnabledPromise = Promise.all([
  featureFlagEnabled("autofill-scorecard:v3c"),
  featureFlagEnabled("autofill-scorecard:v3d"),
]).then(([v3c, v3d]) => v3c || v3d);

onDocumentLoaded(() => {
  v3EnabledPromise.then((v3Enabled) => {
    const legacyMode = !v3Enabled;

    const { start } = createScorecardV3Script({
      getScorecardFields,
      transformText,
      legacyMode,
      learnMoreUrl: legacyMode
        ? undefined
        : "https://help.brighthire.ai/en/articles/14036312-brighthire-scorecard-autofill-for-workday",

      getTooltipText,

      // Always use the narrow/vertical layout for Workday to ensure the button
      // is visible at the bottom of the UI, regardless of container width.
      forceNarrowLayout: true,

      insertUI: async (uiContainer) => {
        // Re-evaluate the page type against the current DOM rather than
        // trusting `cachedPageType`. SPA-navigation races (e.g. moving
        // from "Give Interview Feedback" to "Manage Interview Feedback")
        // can leave the cache stale at the moment insertUI runs, which
        // would otherwise inject the autofill UI into a read-only review
        // page. Refusing to insert here is the last-line defense against
        // any gap in the message-ordering logic upstream.
        const pageType = await getPageType();
        if (pageType === null) return;

        // Additionally require at least one editable scorecard field —
        // either a per-question scorecard row OR an overall comment /
        // general-notes textarea. The read-only "Manage Interview
        // Feedback" page reuses the same `[title="Interview Feedback"]`
        // section heading but has neither, so it correctly bails here.
        // We must accept "general notes only" pages because some Workday
        // tenants render only an Overall Rating + Overall Comment with
        // no per-question rows.
        const fields = await getScorecardFields();
        if (fields.length === 0) {
          const generalNotesField = await getGeneralNotesField();
          if (!generalNotesField?.editor) return;
        }

        if (pageType === "questionnaireTask") {
          const editPageSelector: string = SELECTORS.editPage.join(",");
          const editPage =
            document.querySelector<HTMLElement>(editPageSelector);
          if (!editPage) return;

          const pageHeaderSelector: string = SELECTORS.pageHeader.join(",");
          const titleContainer = editPage?.querySelector(pageHeaderSelector);
          if (!titleContainer) return;

          uiContainer.style.margin = "8px";
          titleContainer.after(uiContainer);
          return;
        }

        const titleContainer = document.querySelector<HTMLElement>(
          SELECTORS.interviewFeedbackTitleEl,
        )?.parentElement;
        if (!titleContainer) return;

        titleContainer.parentElement?.insertBefore(
          uiContainer,
          titleContainer.nextSibling,
        );
      },

      formatting: { mode: "plaintext" },

      addNotesToField: (editor, note) => {
        const textarea = editor as HTMLTextAreaElement;
        if (textarea.value) {
          textarea.value += "\n\n";
        }
        textarea.value += note;
        textarea.dispatchEvent(new Event("input", { bubbles: true }));
        textarea.dispatchEvent(new Event("change", { bubbles: true }));
      },

      getGeneralNotesField: () => getGeneralNotesField(),

      onTabUrlChanged: async () => {
        await signalInterviewIntentIfFeedbackPage();
        // Returning `false` causes the framework to remove an existing
        // `.bh-scorecard-ui` from the page, so we must accurately report
        // whether the current page is a scorecard page (i.e. one of our
        // three recognized page types). Without this, the UI would stay
        // mounted on read-only review pages like "Manage Interview
        // Feedback" that share the "Interview Feedback" section heading
        // but aren't editable. `signalInterviewIntentIfFeedbackPage` already
        // refreshed `cachedPageType`.
        return cachedPageType !== null;
      },

      transformStructuredSummary: legacyMode
        ? undefined
        : (sections) => renderSummarySectionsToPlainText(sections),

      transformStructuredQuestion: legacyMode
        ? undefined
        : (item) => renderBulletsToPlainText(item.bullets ?? []),

      transformMarkdownSummary: legacyMode
        ? undefined
        : (markdown) => renderMarkdownToPlainText(markdown),

      onInit: () => {
        getUiConfig("workday.rateInterview").then((uiConfig) => {
          if (uiConfig) {
            SELECTORS = {
              ...FALLBACK_CONFIG["workday.rateInterview"],
              ...uiConfig,
            };
          }
          // Now that selectors are loaded, check whether we're already on a
          // feedback / rate-interview / questionnaire page (the extension may
          // have loaded directly onto one) and signal interview intent if so.
          signalInterviewIntentIfFeedbackPage();
        });
      },
    });

    start();
  });
});
