/**
 * Shared HTML rendering utilities for V3 structured scorecard notes.
 * Used by ATS adapters (Greenhouse, Ashby, etc.) to convert structured
 * bullets and summary sections into editor-ready HTML with citation links.
 */

import { getUrlPrefix } from "../../../utils/storage";

/**
 * Resolves the base URL for an interview given its call ID.
 * Used by HTML-mode ATS adapters to build citation timestamp links.
 */
export const buildInterviewBaseUrl = async (
  callId: string,
): Promise<string> => {
  const urlPrefix = await getUrlPrefix();
  return `${urlPrefix}/interview/${callId}`;
};

/**
 * Escapes HTML special characters to prevent XSS when interpolating
 * untrusted content (e.g., LLM-generated text) into HTML strings.
 */
const escapeHtml = (text: string): string =>
  text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");

/**
 * Strips dangerous URL protocols (e.g. javascript:, data:, vbscript:) to
 * prevent protocol-based XSS when interpolating untrusted URLs into href
 * attributes. Only allows http, https, and relative URLs.
 */
const sanitizeUrl = (url: string): string => {
  const trimmed = url.trim();
  // Allow only http/https/relative URLs; blank out anything else
  if (/^(https?:\/\/|\/(?!\/)|#)/i.test(trimmed)) return trimmed;
  return "#";
};

/**
 * Formats a duration in seconds to a display timestamp like "[5:23]" or "[1:02:03]".
 * Matches the Python format_duration function in brighthire/utils/string.py.
 */
const formatTimestamp = (totalSeconds: number): string => {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const ss = seconds.toString().padStart(2, "0");
  if (hours > 0) {
    return `[${hours}:${minutes.toString().padStart(2, "0")}:${ss}]`;
  }
  return `[${minutes}:${ss}]`;
};

/**
 * Creates a timestamp link element pointing to the interview at the given time.
 * Uses encodeURI to ensure the URL is safe for href attribute injection.
 */
const createTimestampLink = (timestamp: string, href: string): string =>
  `<a href="${encodeURI(href)}" target="_blank" rel="noopener noreferrer">${timestamp}</a>`;

/**
 * Minimal markdown-to-HTML parser.
 *
 * Handles:
 *   - Headings        (#, ##, ###, …) → <p><strong>text</strong></p>
 *   - Unordered items (- or *, any indent) → <p>• text</p>
 *   - Ordered items   (1. 2. …, any indent) → <p>1. text</p>
 *   - Links           [text](url)
 *   - Bold            **text** or __text__
 *   - Everything else → <p>text</p>  (blank lines are skipped)
 */
const markdownToHtml = (markdown: string): string => {
  const lines = markdown.split("\n");
  const parts: string[] = [];

  for (const rawLine of lines) {
    const line = rawLine.trimEnd();

    // Skip blank lines
    if (line.trim() === "") continue;

    // Inline helpers applied to the text content of each line
    const applyInline = (text: string): string =>
      escapeHtml(text)
        // Links: [text](url) — re-match after escaping since [] () are not escaped
        .replace(
          /\[([^\]]+)\]\(([^)]+)\)/g,
          (_m: string, linkText: string, url: string) =>
            `<a href="${sanitizeUrl(
              url,
            )}" target="_blank" rel="noopener noreferrer">${linkText}</a>`,
        )
        // Bold: **text** or __text__
        .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
        .replace(/__([^_]+)__/g, "<strong>$1</strong>");

    // Headings (must be at start of line, no leading indent)
    const headingMatch = /^(#{1,6})\s+(.+)$/.exec(line);
    if (headingMatch) {
      parts.push(`<p><strong>${applyInline(headingMatch[2])}</strong></p>`);
      continue;
    }

    // Unordered list items (- or *, any leading whitespace)
    const unorderedMatch = /^\s*[-*]\s+(.+)$/.exec(line);
    if (unorderedMatch) {
      parts.push(`<p>\u2022&nbsp;${applyInline(unorderedMatch[1])}</p>`);
      continue;
    }

    // Ordered list items (1. 2. etc., any leading whitespace)
    const orderedMatch = /^\s*(\d+)\.\s+(.+)$/.exec(line);
    if (orderedMatch) {
      parts.push(
        `<p>${orderedMatch[1]}.&nbsp;${applyInline(orderedMatch[2])}</p>`,
      );
      continue;
    }

    // Plain paragraph
    parts.push(`<p>${applyInline(line)}</p>`);
  }

  return parts.join("");
};

/**
 * Converts custom template markdown to HTML.
 * Pre-processes BrightHire timestamp links [text](?t=seconds) before conversion.
 *
 * @param timestampParam - Query parameter name for timestamps (default: "t").
 *   Use "timestamp" for Ashby to avoid their editor's special handling of ?t=.
 */
export const renderMarkdownToHtml = (
  markdown: string,
  interviewBaseUrl: string,
  timestampParam = "t",
): string => {
  // Process timestamp links: [text](?t=seconds) -> [text](full-url)
  // These are BrightHire-specific links that need the full interview URL
  const processedMarkdown = markdown.replace(
    /\[([^\]]+)\]\(\?t=(\d+)\)/g,
    (_match, text, seconds) => {
      const href = `${interviewBaseUrl}?${timestampParam}=${seconds}`;
      return `[${text}](${href})`;
    },
  );

  return markdownToHtml(processedMarkdown);
};

/**
 * Converts custom template markdown to plain text.
 * Strips markdown formatting, converts bullets to "• ", and removes timestamp links.
 * Used for ATSs that don't support HTML (e.g., Workday).
 */
export const renderMarkdownToPlainText = (markdown: string): string => {
  const lines = markdown.split("\n");
  const result: string[] = [];

  for (const line of lines) {
    let processed = line.trim();

    // Remove timestamp links entirely: [text](?t=seconds) -> ""
    processed = processed.replace(/\s*\[([^\]]+)\]\(\?t=\d+\)/g, "");

    // Remove other markdown links: [text](url) -> text
    processed = processed.replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");

    // Convert headers to plain text (remove # prefix)
    if (processed.match(/^#{1,6}\s/)) {
      processed = processed.replace(/^#{1,6}\s+/, "");
    }

    // Convert bullet points
    if (processed.startsWith("- ") || processed.startsWith("* ")) {
      processed = `• ${processed.slice(2)}`;
    }

    // Remove bold/italic markers
    processed = processed.replace(/\*\*([^*]+)\*\*/g, "$1"); // **bold**
    processed = processed.replace(/\*([^*]+)\*/g, "$1"); // *italic*
    processed = processed.replace(/__([^_]+)__/g, "$1"); // __bold__
    processed = processed.replace(/_([^_]+)_/g, "$1"); // _italic_

    result.push(processed);
  }

  return result.join("\n");
};

/**
 * Renders citation timestamps as links appended to a line of text.
 * Citations are AI note start_time values in seconds.
 * Each link points to /interview/{callId}?{timestampParam}={seconds}.
 *
 * @param timestampParam - Query parameter name for timestamps (default: "t").
 *   Use "timestamp" for Ashby to avoid their editor's special handling of ?t=.
 */
export const renderCitationLinks = (
  citations: number[],
  interviewBaseUrl: string,
  timestampParam = "t",
): string => {
  if (citations.length === 0) return "";
  // Deduplicate and sort citations
  const unique = [...new Set(citations)].sort((a, b) => a - b);
  const links = unique.map((seconds) =>
    createTimestampLink(
      formatTimestamp(seconds),
      `${interviewBaseUrl}?${timestampParam}=${seconds}`,
    ),
  );
  return `&nbsp;${links.join("&nbsp;")}`;
};

/**
 * Renders structured bullets into an HTML string with bullet characters
 * and citation timestamp links.
 *
 * @param timestampParam - Query parameter name for timestamps (default: "t").
 *   Use "timestamp" for Ashby to avoid their editor's special handling of ?t=.
 */
export const renderBulletsToHtml = (
  bullets: ScorecardBullet[],
  interviewBaseUrl: string,
  timestampParam = "t",
): string => {
  const lines = bullets
    .filter((b) => b.text)
    .map((b) => {
      const escapedText = escapeHtml(b.text);
      const citations = renderCitationLinks(
        b.citations,
        interviewBaseUrl,
        timestampParam,
      );
      return `<p>\u2022&nbsp;${escapedText}${citations}</p>`;
    });
  return lines.join("");
};

/**
 * Renders structured summary sections into an HTML string with bold headers.
 *
 * @param timestampParam - Query parameter name for timestamps (default: "t").
 *   Use "timestamp" for Ashby to avoid their editor's special handling of ?t=.
 */
export const renderSummarySectionsToHtml = (
  sections: ScorecardSummarySection[],
  interviewBaseUrl: string,
  timestampParam = "t",
): string => {
  const rendered: string[] = [];
  for (const section of sections) {
    if (!section.header && (!section.bullets || section.bullets.length === 0)) {
      continue;
    }
    const header = section.header
      ? `<p><strong>${escapeHtml(section.header)}</strong></p>`
      : "";
    const body = renderBulletsToHtml(
      section.bullets,
      interviewBaseUrl,
      timestampParam,
    );
    if (header && body) {
      rendered.push(`${header}${body}`);
    } else if (header) {
      rendered.push(header);
    } else if (body) {
      rendered.push(body);
    }
  }
  return rendered.join("<p><br></p>");
};

/**
 * Renders structured bullets into a plain-text string with bullet characters.
 * Used by plaintext-mode ATS adapters (Lever, SmartRecruiters, Workday).
 */
export const renderBulletsToPlainText = (bullets: ScorecardBullet[]): string =>
  bullets
    .filter((b) => b.text)
    .map((b) => `\u2022 ${b.text}`)
    .join("\n");

/**
 * Renders structured summary sections into a plain-text string.
 * Used by plaintext-mode ATS adapters (Lever, SmartRecruiters, Workday).
 */
export const renderSummarySectionsToPlainText = (
  sections: ScorecardSummarySection[],
): string =>
  sections
    .filter((s) => s.header || s.bullets?.length)
    .map((s) =>
      [s.header, ...(s.bullets?.map((b) => `• ${b.text}`) || [])].join("\n"),
    )
    .join("\n\n");
