import { sendGAEvent, sendMessageWithTabId } from "./message";
import {
  getSuppressScorecardFeedback,
  getUrlPrefix,
  setSuppressScorecardFeedback,
} from "./storage";

let feedbackEl: HTMLElement | null = null;

type FeedbackOptions = {
  /** Delay in ms before showing the popup */
  openDelay?: number;
};

/**
 * Shows a feedback popup in the ATS page with thumbs up/down and optional
 * commentary. Used after scorecard v3 draft completion on Greenhouse.
 *
 * Sends a "scorecardFeedback" message back to the frontend for Segment tracking.
 */
export const showFeedback = async (
  opts: FeedbackOptions = {},
): Promise<void> => {
  // User has opted out of seeing this popup again.
  if (await getSuppressScorecardFeedback()) {
    return;
  }

  // Remove any existing feedback popup
  if (feedbackEl) {
    feedbackEl.remove();
    feedbackEl = null;
  }

  feedbackEl = await createFeedbackElement();
  initFeedbackActions(feedbackEl, opts);

  if (document.body) {
    document.body.appendChild(feedbackEl);
  } else {
    document.addEventListener(
      "DOMContentLoaded",
      () => document.body.appendChild(feedbackEl as HTMLElement),
      { once: true },
    );
  }
};

async function createFeedbackElement(): Promise<HTMLElement> {
  const root = document.createElement("div");
  root.classList.add("bh-feedback-container");

  const urlPrefix = await getUrlPrefix();

  root.innerHTML = `
    <div class="bh-feedback">
      <div class="bh-feedback-header">
        <img src="${urlPrefix}/static/images/logo_ui_alert.svg" class="bh-feedback-logo" />
        <span class="bh-feedback-title">Was the autofill scorecard feature helpful?</span>
        <div class="bh-feedback-close">
          <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg" role="button">
            <path d="M14.375 5.625L5.625 14.375M14.375 14.375L5.625 5.625L14.375 14.375Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </div>
      </div>

      <div class="bh-feedback-buttons">
        <button class="bh-feedback-btn" data-rating="positive" aria-label="Thumbs up">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/>
          </svg>
        </button>
        <button class="bh-feedback-btn" data-rating="negative" aria-label="Thumbs down">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3zm7-13h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/>
          </svg>
        </button>
      </div>

      <div class="bh-feedback-comment">
        <textarea class="bh-feedback-textarea" placeholder="Any feedback you'd like to share?" rows="3" maxlength="500"></textarea>
        <div class="bh-feedback-actions">
          <button class="bh-feedback-suppress">Don't show again</button>
          <button class="bh-feedback-submit">Submit feedback</button>
        </div>
      </div>

      <div class="bh-feedback-thanks" style="display: none;">
        <span>Thanks for your feedback!</span>
      </div>
    </div>
  `;

  return root;
}

function initFeedbackActions(
  el: HTMLElement,
  { openDelay = 2000 }: FeedbackOptions,
): void {
  let selectedRating: "positive" | "negative" | null = null;

  // Show with delay
  setTimeout(() => {
    el.classList.add("bh-feedback-show");
  }, openDelay);

  // Close button
  const closeBtn = el.querySelector(".bh-feedback-close") as HTMLElement;
  closeBtn.onclick = () => {
    sendGAEvent({
      action: "scorecard_v3_feedback",
      eventCategory: "user_feedback",
      eventLabel: "dismissed",
    });
    hideFeedback(el);
  };

  // Thumbs buttons
  const buttons = el.querySelectorAll<HTMLButtonElement>(".bh-feedback-btn");
  const commentSection = el.querySelector(
    ".bh-feedback-comment",
  ) as HTMLElement;
  const buttonsSection = el.querySelector(
    ".bh-feedback-buttons",
  ) as HTMLElement;

  buttons.forEach((btn) => {
    btn.onclick = () => {
      selectedRating = btn.dataset.rating as "positive" | "negative";

      // Highlight selected button, dim the other
      buttons.forEach((b) => {
        b.classList.remove(
          "bh-feedback-btn-selected",
          "bh-feedback-btn-dimmed",
        );
        if (b === btn) {
          b.classList.add("bh-feedback-btn-selected");
        } else {
          b.classList.add("bh-feedback-btn-dimmed");
        }
      });
    };
  });

  // Submit button
  const submitBtn = el.querySelector(".bh-feedback-submit") as HTMLElement;
  const textarea = el.querySelector(
    ".bh-feedback-textarea",
  ) as HTMLTextAreaElement;

  submitBtn.onclick = () => {
    if (!selectedRating) return;

    const comment = textarea.value.trim() || undefined;

    // Send message to frontend for Segment tracking
    sendMessageWithTabId({
      action: "scorecardFeedback",
      payload: {
        scorecardFeedback: {
          rating: selectedRating,
          comment,
        },
      },
    });

    sendGAEvent({
      action: "scorecard_v3_feedback",
      eventCategory: "user_feedback",
      eventLabel: selectedRating,
      value: comment,
    });

    // Show thanks message
    buttonsSection.style.display = "none";
    commentSection.style.display = "none";
    const thanks = el.querySelector(".bh-feedback-thanks") as HTMLElement;
    thanks.style.display = "block";

    // Auto-dismiss after 2s
    setTimeout(() => hideFeedback(el), 2000);
  };

  // "Don't show again" button — persist the suppress flag and close.
  // Any rating/comment the user entered is intentionally discarded.
  const suppressBtn = el.querySelector(".bh-feedback-suppress") as HTMLElement;
  suppressBtn.onclick = async () => {
    sendGAEvent({
      action: "scorecard_v3_feedback",
      eventCategory: "user_feedback",
      eventLabel: "suppressed",
    });
    await setSuppressScorecardFeedback(true);
    hideFeedback(el);
  };
}

function hideFeedback(el: HTMLElement): void {
  el.classList.add("bh-feedback-hide");
  el.addEventListener(
    "animationend",
    () => {
      el.remove();
      feedbackEl = null;
    },
    { once: true },
  );
}
