import {
  checkIcon,
  closeIcon,
  infoIcon,
  sparkleIcon,
  warningIcon,
} from "./icons";
import { logVerbose } from "./logVerbose";
import { sendGAEvent, sendMessageWithTabId } from "./message";

export const BH_ALERT_CLASS = "bh-alert";

/** Alert type determines icon and background color */
export type AlertType = "success" | "info" | "error" | "ai";

/** Map alert types to their icons */
const ALERT_ICONS: Record<AlertType, string> = {
  success: checkIcon,
  info: infoIcon,
  error: warningIcon,
  ai: sparkleIcon,
};

/**
 * Creates the alert element HTML structure.
 * Exported for use in Storybook.
 */
export type CreateAlertElementOptions = {
  type?: AlertType;
  title: string;
  body?: string;
  action?: {
    displayText: string;
  };
};

const getAlertTypeClass = (type: AlertType): string => {
  switch (type) {
    case "info":
      return " bh-info";
    case "error":
      return " bh-error";
    case "ai":
      return " bh-ai";
    default:
      return "";
  }
};

export const createAlertElement = ({
  type = "success",
  title,
  body,
  action,
}: CreateAlertElementOptions): HTMLElement => {
  const container = document.createElement("div");
  container.classList.add("bh-alert-container", "bh-show");

  const icon = ALERT_ICONS[type];
  const typeClass = getAlertTypeClass(type);
  // AI alerts get the sparkle animation
  const iconClass =
    type === "ai" ? "bh-alert-icon bh-sparkle-animated" : "bh-alert-icon";

  container.innerHTML = `
    <div class="bh-spacer-l"></div>

    <div class="bh-alert${typeClass}">
      <div class="${iconClass}">${icon}</div>

      <div>
       <div class="bh-alert-title">${title}</div>
        <span class="bh-alert-body">${body ?? ""}</span>
      </div>

      <div class="bh-alert-close">${closeIcon}</div>

        ${
          action
            ? `<button class="bh-alert-action">${action.displayText}</button>`
            : ""
        }
    </div>

    <div class="bh-spacer-r"></div>
  `;

  return container;
};

let rootEl: HTMLElement;
let drawerObserver: MutationObserver;

export const clearAlert = (): void => {
  rootEl?.querySelector<HTMLElement>(".bh-alert-close")?.click();
};

export const showAlert = (alertConfig: AlertConfig): Alert | null => {
  if (!alertConfig) return null;

  const alertManager = buildAlert(alertConfig);
  logVerbose("calling alertManager.mount();", alertManager);
  alertManager.mount();

  return alertManager;
};

/**
 * Helpers
 */
function buildAlert(opts: AlertConfig): Alert {
  logVerbose("buildAlert", opts);
  const el = buildAlertElement(opts);
  const actions = initAlertActions(el, opts);

  makeResponsive(el);

  return {
    el,
    ...actions,
  };
}

function buildAlertElement({
  type,
  title,
  body,
  action,
  afterAction,
}: AlertConfig): HTMLElement {
  // Use the shared createAlertElement, but we need to manage rootEl for reuse
  if (!rootEl) {
    rootEl = createAlertElement({
      type,
      title,
      body,
      action,
    });
  } else {
    // Update existing rootEl with new content
    const newEl = createAlertElement({
      type,
      title,
      body,
      action,
    });
    rootEl.innerHTML = newEl.innerHTML;
    rootEl.className = newEl.className;
  }

  if (action) {
    const bodyEl = rootEl.querySelector(".bh-alert-body") as HTMLElement;
    const actionEl = rootEl.querySelector(".bh-alert-action") as HTMLElement;
    actionEl.onclick = (e) => {
      e.preventDefault();
      if (action.actionName) {
        sendMessageWithTabId({ action: action.actionName });
      }
      action.onClick?.();
      if (afterAction) {
        const titleEl = rootEl.querySelector(".bh-alert-title") as HTMLElement;
        titleEl.innerText = afterAction.title;
        bodyEl.innerText = afterAction.body;
      }
    };
  }

  return rootEl;
}

function initAlertActions(
  el: HTMLElement,
  { openDelay, duration }: AlertConfig,
): Pick<Alert, AlertEvent> {
  const timeouts = {
    open: undefined as Timeout,
    close: undefined as Timeout,
  };

  const dispatch = (eventName: AlertEvent): void => {
    const event = new Event(eventName);
    el.dispatchEvent(event);
  };

  const onAnimationEnd = (handler: () => void): void =>
    el.addEventListener("animationend", handler, { once: true });

  const hide = (): void => {
    el.classList.add("hide");
    dispatch("hide");
    if (el.classList.contains("bh-show")) {
      onAnimationEnd(() => el.classList.remove("bh-show"));
    }
  };
  const closeIcon = el.querySelector(".bh-alert-close") as HTMLElement;
  closeIcon.onclick = (e) => {
    if (e.isTrusted) {
      sendGAEvent({
        action: "autofill_scorecard",
        eventCategory: "call_review",
        eventLabel: "dismiss_alert",
      });
    }
    hide();
  };

  const show = (): void => {
    clearTimeout(timeouts.open);
    timeouts.open = setTimeout(() => {
      el.classList.remove("hide");
      el.classList.add("bh-show");
      dispatch("show");
    }, openDelay);

    clearTimeout(timeouts.close);
    if (duration !== undefined) {
      timeouts.close = setTimeout(hide, duration);
    }
  };

  const mount = (): void => {
    const _mount = (): void => {
      if (el.parentElement !== document.body) {
        document.body.appendChild(el);
      }
      dispatch("mount");
      show();
    };

    if (document.body) {
      _mount();
    } else {
      document.addEventListener("DOMContentLoaded", _mount, { once: true });
    }
  };

  const destroy = (): void => {
    hide();
    onAnimationEnd(() => {
      el.remove();
      dispatch("destroy");
    });
  };

  return {
    show,
    hide,
    mount,
    destroy,
  };
}

/**
 * Sets CSS variables when drawer opens / closes that allow for responsive
 * styling of the alert
 */
function makeResponsive(el: HTMLElement): void {
  const drawer = document.getElementById("brighthire-drawer");
  if (drawer === null) return;

  if (drawerObserver) {
    drawerObserver.disconnect();
  }

  const onDrawerChange = (): void => {
    const drawerVisible = drawer.classList.contains("brighthire-visible");

    document.body.style.setProperty(
      "--bh-drawer-width",
      `${drawerVisible ? drawer.clientWidth : 0}px`,
    );
  };
  onDrawerChange();
  drawerObserver = new MutationObserver(onDrawerChange);
  drawerObserver.observe(drawer, { attributeFilter: ["class"] });

  el.addEventListener("hide", () => drawerObserver.disconnect(), {
    once: true,
  });
}

/**
 * Types
 */
type Timeout = undefined | ReturnType<typeof setTimeout>;
type AlertEvent = "mount" | "destroy" | "show" | "hide";

type Alert<E extends HTMLElement = HTMLElement> = {
  [key in AlertEvent]: () => void;
} & {
  el: E;
};
