/**
 * Returns a copy of the given string with all but the first occurrence of each
 * provided header removed
 */
export const formatHeadersNonHtml = (s: string, headers: string[]): string => {
  let result = s;
  headers.forEach((header) => {
    const startIdx = result.indexOf(header);
    if (startIdx === -1) return;
    const regex = new RegExp(`^${header}\n\n`, "gm");
    const preHeader = result.slice(0, startIdx);
    const headerRemoved = result
      .slice(startIdx + header.length)
      .replace(regex, "");
    result = preHeader + header + headerRemoved;
  });
  return result;
};

/**
 * Strips whitespace from input text
 */
export const transformText = (text: string): string =>
  text.replace(/[\s*]/g, "");

/**
 * Escape HTML special characters to prevent XSS when inserting
 * untrusted text into innerHTML or similar APIs.
 */
export const escapeHtml = (unsafe: string): string => {
  return unsafe
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
};
