import { chevronDownIcon, infoIcon } from "./icons";
import { createSVGFromString } from "./utils";

/**
 * Summary style values matching the OverallSummaryStyle GraphQL enum.
 */
export const BH_SUMMARY_STYLE_TOPIC = "BY_TOPIC";
export const BH_SUMMARY_STYLE_QANDA = "BY_QUESTION";
export const BH_SUMMARY_STYLE_AI_INTERVIEW_EVALUATION =
  "AI_INTERVIEW_EVALUATION";

/**
 * BrightHire built-in summary options. These have id=null; the style is
 * carried in overallSummaryStyle and sent directly to the mutation.
 */
const BH_DEFAULT_TEMPLATES: AutofillSummaryTemplate[] = [
  {
    id: null,
    name: "Topic summary",
    description:
      "Summarizes important topics from the interview not already covered in your scorecard questions.",
    overallSummaryStyle: BH_SUMMARY_STYLE_TOPIC,
  },
  {
    id: null,
    name: "Q&A summary",
    description:
      "Summarizes questions asked and answers from the interview not already captured in your scorecard.",
    overallSummaryStyle: BH_SUMMARY_STYLE_QANDA,
  },
];

/**
 * Extra BrightHire built-in option that only makes sense for AI Interview
 * calls — sourced from the call's AI evaluation rather than an LLM pass
 * over the transcript. Prepended to BH_DEFAULT_TEMPLATES so it sits at the
 * top of the dropdown for AI Interview scorecards.
 */
const BH_AI_INTERVIEW_EVALUATION_TEMPLATE: AutofillSummaryTemplate = {
  id: null,
  name: "AI Interview Evaluation",
  description:
    "Uses the AI Interview's evaluation (summary, score, per-question answers) as the Key Takeaways.",
  overallSummaryStyle: BH_SUMMARY_STYLE_AI_INTERVIEW_EVALUATION,
};

/**
 * Single global click listener for closing all open dropdowns.
 * This avoids adding a new listener on every render.
 */
let globalDropdownListenerInitialized = false;
const initGlobalDropdownListener = (): void => {
  if (globalDropdownListenerInitialized) return;
  globalDropdownListenerInitialized = true;

  document.addEventListener("click", () => {
    document
      .querySelectorAll(".bh-template-dropdown__menu--open")
      .forEach((el) => {
        el.classList.remove("bh-template-dropdown__menu--open");
      });
    document.querySelectorAll(".bh-template-dropdown--open").forEach((el) => {
      el.classList.remove("bh-template-dropdown--open");
    });
  });
};

type ToggleSwitchParams = {
  checked: boolean;
  onChange: (checked: boolean) => void;
  disabled?: boolean;
};

/**
 * Creates a toggle switch component
 */
export const createToggleSwitch = ({
  checked,
  onChange,
  disabled = false,
}: ToggleSwitchParams): HTMLElement => {
  const container = document.createElement("label");
  container.className = "bh-toggle-switch";
  if (disabled) {
    container.classList.add("bh-toggle-switch--disabled");
  }

  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = checked;
  input.disabled = disabled;
  input.className = "bh-toggle-switch__input";
  input.addEventListener("change", () => {
    onChange(input.checked);
  });

  const slider = document.createElement("span");
  slider.className = "bh-toggle-switch__slider";

  container.appendChild(input);
  container.appendChild(slider);

  return container;
};

type DropdownSection = {
  label?: string;
  templates: AutofillSummaryTemplate[];
};

/**
 * Returns a stable string key for a template used to identify the selection.
 * Custom templates are keyed by their UUID; BH built-ins by their style value.
 */
const templateKey = (t: AutofillSummaryTemplate): string =>
  t.id ?? t.overallSummaryStyle ?? "";

type DropdownParams = {
  sections: DropdownSection[];
  selectedTemplateId: string | null;
  selectedStyle: string | null | undefined;
  onSelect: (template: AutofillSummaryTemplate) => void;
  disabled?: boolean;
};

/**
 * Creates a dropdown component for selecting autofill templates.
 * Supports optional section headers to group options (e.g. "BrightHire default", "My templates").
 * Uses a single global click listener that is reused across renders.
 */
export const createTemplateDropdown = ({
  sections,
  selectedTemplateId,
  selectedStyle,
  onSelect,
  disabled = false,
}: DropdownParams): HTMLElement => {
  const container = document.createElement("div");
  container.className = "bh-template-dropdown";
  if (disabled) {
    container.classList.add("bh-template-dropdown--disabled");
  }

  const allTemplates = sections.flatMap((s) => s.templates);

  // Resolve the currently-selected template using the compound key.
  // For custom templates match by id; for BH built-ins match by style.
  const selectedKey =
    selectedTemplateId != null ? selectedTemplateId : (selectedStyle ?? "");
  const selected =
    allTemplates.find((t) => templateKey(t) === selectedKey) || allTemplates[0];

  // Trigger button
  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "bh-template-dropdown__trigger";
  trigger.disabled = disabled;

  const triggerText = document.createElement("span");
  triggerText.className = "bh-template-dropdown__trigger-text";
  triggerText.textContent = selected?.name || "Select template";
  trigger.appendChild(triggerText);

  const chevron = createSVGFromString(chevronDownIcon);
  chevron.classList.add("bh-template-dropdown__chevron");
  trigger.appendChild(chevron);

  container.appendChild(trigger);

  // Dropdown menu
  const menu = document.createElement("div");
  menu.className = "bh-template-dropdown__menu";

  sections.forEach((section) => {
    // Section header (optional)
    if (section.label) {
      const header = document.createElement("div");
      header.className = "bh-template-dropdown__section-header";
      header.textContent = section.label;
      menu.appendChild(header);
    }

    section.templates.forEach((template) => {
      const option = document.createElement("button");
      option.type = "button";
      option.className = "bh-template-dropdown__option";
      if (templateKey(template) === templateKey(selected)) {
        option.classList.add("bh-template-dropdown__option--selected");
      }

      const optionName = document.createElement("span");
      optionName.className = "bh-template-dropdown__option-name";
      optionName.textContent = template.name;
      option.appendChild(optionName);

      if (template.description) {
        const optionDesc = document.createElement("span");
        optionDesc.className = "bh-template-dropdown__option-desc";
        optionDesc.textContent = template.description;
        option.appendChild(optionDesc);
      }

      option.addEventListener("click", (e) => {
        e.stopPropagation();
        onSelect(template);
        triggerText.textContent = template.name;
        menu.classList.remove("bh-template-dropdown__menu--open");
        container.classList.remove("bh-template-dropdown--open");

        // Update selected state
        menu
          .querySelectorAll(".bh-template-dropdown__option--selected")
          .forEach((el) => {
            el.classList.remove("bh-template-dropdown__option--selected");
          });
        option.classList.add("bh-template-dropdown__option--selected");
      });

      menu.appendChild(option);
    });
  });

  container.appendChild(menu);

  // Toggle menu on trigger click
  trigger.addEventListener("click", (e) => {
    e.stopPropagation();
    const isOpen = menu.classList.contains("bh-template-dropdown__menu--open");
    if (isOpen) {
      menu.classList.remove("bh-template-dropdown__menu--open");
      container.classList.remove("bh-template-dropdown--open");
    } else {
      menu.classList.add("bh-template-dropdown__menu--open");
      container.classList.add("bh-template-dropdown--open");
    }
  });

  // Use the shared global click listener to close dropdowns
  initGlobalDropdownListener();

  return container;
};

/**
 * Creates an info icon with tooltip
 */
export const createInfoIcon = (tooltipText: string): HTMLElement => {
  const container = document.createElement("div");
  container.className = "bh-info-icon";

  const icon = createSVGFromString(infoIcon);
  icon.classList.add("bh-info-icon__svg");
  container.appendChild(icon);

  const tooltip = document.createElement("div");
  tooltip.className = "bh-info-icon__tooltip";
  tooltip.textContent = tooltipText;
  container.appendChild(tooltip);

  return container;
};

const DETAIL_LEVELS: { value: string; label: string }[] = [
  { value: "LOW", label: "Brief" },
  { value: "MEDIUM", label: "Standard" },
  { value: "HIGH", label: "Detailed" },
];

type DetailLevelSegmentParams = {
  selectedDetailLevel: string;
  onDetailLevelChange: (detailLevel: string) => void;
  disabled?: boolean;
};

/**
 * Creates a Brief / Standard / Detailed segmented control.
 * Renders as a second row below the toggle + summary dropdown row.
 */
export const createDetailLevelSegment = ({
  selectedDetailLevel,
  onDetailLevelChange,
  disabled = false,
}: DetailLevelSegmentParams): HTMLElement => {
  const container = document.createElement("div");
  container.className = "bh-detail-segment";
  if (disabled) {
    container.classList.add("bh-detail-segment--disabled");
  }

  DETAIL_LEVELS.forEach(({ value, label }) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "bh-detail-segment__btn";
    btn.textContent = label;
    btn.disabled = disabled;
    if (value === selectedDetailLevel) {
      btn.classList.add("bh-detail-segment__btn--selected");
    }

    btn.addEventListener("click", () => {
      container
        .querySelectorAll(".bh-detail-segment__btn--selected")
        .forEach((el) => {
          el.classList.remove("bh-detail-segment__btn--selected");
        });
      btn.classList.add("bh-detail-segment__btn--selected");
      onDetailLevelChange(value);
    });

    container.appendChild(btn);
  });

  return container;
};

type AutofillOptionsParams = {
  templates: AutofillSummaryTemplate[];
  includeAdditionalSummary: boolean;
  selectedTemplateId: string | null;
  selectedStyle: string | null | undefined;
  selectedDetailLevel: string;
  /**
   * When true the "AI Interview Evaluation" BrightHire default option is
   * surfaced at the top of the dropdown. Has no effect on non-AI calls.
   */
  isAiInterview?: boolean;
  getTooltipText?: (hasCustomTemplates: boolean) => string;
  onIncludeAdditionalSummaryChange: (checked: boolean) => void;
  onTemplateSelect: (template: AutofillSummaryTemplate) => void;
  onDetailLevelChange: (detailLevel: string) => void;
  disabled?: boolean;
};

/**
 * Builds the grouped dropdown sections from the flat template list.
 *
 * Section layout:
 *   BrightHire default — always present (2 built-in options, plus an extra
 *                        "AI Interview Evaluation" option for AI Interview calls)
 *   My templates       — custom templates owned by the current user (if any)
 *   Shared templates   — custom templates shared by others in the org (if any)
 */
const buildDropdownSections = (
  customTemplates: AutofillSummaryTemplate[],
  isAiInterview: boolean,
): DropdownSection[] => {
  const defaults = isAiInterview
    ? [BH_AI_INTERVIEW_EVALUATION_TEMPLATE, ...BH_DEFAULT_TEMPLATES]
    : BH_DEFAULT_TEMPLATES;
  const sections: DropdownSection[] = [
    {
      label: "BrightHire default",
      templates: defaults,
    },
  ];

  const myTemplates = customTemplates.filter((t) => t.isOwnTemplate);
  const sharedTemplates = customTemplates.filter((t) => t.isSharedTemplate);

  if (myTemplates.length > 0) {
    sections.push({ label: "My templates", templates: myTemplates });
  }
  if (sharedTemplates.length > 0) {
    sections.push({ label: "Shared templates", templates: sharedTemplates });
  }

  return sections;
};

/**
 * Creates the autofill options section with toggle and template dropdown.
 *
 * The dropdown is always rendered when the toggle is on — even when the user
 * has no custom templates — so that the BrightHire built-in options (Topic
 * summary, Q&A summary) are always accessible.
 */
export const createAutofillOptionsSection = ({
  templates,
  includeAdditionalSummary,
  selectedTemplateId,
  selectedStyle,
  selectedDetailLevel,
  isAiInterview = false,
  getTooltipText,
  onIncludeAdditionalSummaryChange,
  onTemplateSelect,
  onDetailLevelChange,
  disabled = false,
}: AutofillOptionsParams): HTMLElement => {
  const container = document.createElement("div");
  container.className = "bh-autofill-options";

  // Label
  const label = document.createElement("span");
  label.className = "bh-autofill-options__label";
  label.textContent = "Options:";
  container.appendChild(label);

  // Right column: row 1 (toggle + summary) and row 2 (detail level)
  const rightColumn = document.createElement("div");
  rightColumn.className = "bh-autofill-options__right";

  // Row 1: toggle + summary dropdown in bordered pill
  const inputContainer = document.createElement("div");
  inputContainer.className = "bh-autofill-options__inputs";
  if (disabled) {
    inputContainer.classList.add("bh-autofill-options__inputs--disabled");
  }

  // Toggle switch
  const toggle = createToggleSwitch({
    checked: includeAdditionalSummary,
    onChange: onIncludeAdditionalSummaryChange,
    disabled,
  });
  inputContainer.appendChild(toggle);

  // Toggle label
  const toggleLabel = document.createElement("span");
  toggleLabel.className = "bh-autofill-options__toggle-label";
  toggleLabel.textContent = "Include additional summary";
  inputContainer.appendChild(toggleLabel);

  const hasCustomTemplates = templates.length > 0;

  // Info icon tooltip
  const tooltipText = getTooltipText
    ? getTooltipText(hasCustomTemplates)
    : "Adds a summary to the Key Takeaways section when you autofill. Choose between BrightHire's built-in summaries or your custom templates.";
  const infoIconEl = createInfoIcon(tooltipText);
  inputContainer.appendChild(infoIconEl);

  // Template dropdown — always rendered (both BH defaults and any custom templates)
  const dropdownWrapper = document.createElement("div");
  dropdownWrapper.className = "bh-autofill-options__dropdown-wrapper";

  const sections = buildDropdownSections(templates, isAiInterview);
  const dropdown = createTemplateDropdown({
    sections,
    selectedTemplateId,
    selectedStyle,
    onSelect: onTemplateSelect,
    disabled: disabled || !includeAdditionalSummary,
  });
  dropdownWrapper.appendChild(dropdown);
  inputContainer.appendChild(dropdownWrapper);

  // Hide dropdown when toggle is off
  if (!includeAdditionalSummary) {
    dropdownWrapper.classList.add(
      "bh-autofill-options__dropdown-wrapper--hidden",
    );
  }

  rightColumn.appendChild(inputContainer);

  // Row 2: Brief / Standard / Detailed segmented control
  const detailSegment = createDetailLevelSegment({
    selectedDetailLevel,
    onDetailLevelChange,
    disabled,
  });
  rightColumn.appendChild(detailSegment);

  container.appendChild(rightColumn);

  return container;
};
