import { clearAlert, showAlert } from "../../../utils/alert";
import { showConfetti } from "../../../utils/confetti";
import { featureFlagEnabled } from "../../../utils/featureFlag";
import { showFeedback } from "../../../utils/feedback";
import {
  addMessageListener,
  sendMessageWithTabId,
} from "../../../utils/message";
import { BH_SUMMARY_STYLE_TOPIC } from "./autofillOptions";
import { createConfirmAutofillModal, createScorecardUI } from "./ui";

export const SCORECARD_AUTOFILL_UI_DISABLED_FEATURE =
  "browser-extension:scorecard-autofill-ui:disabled";

/**
 * Per-ATS formatting configuration.
 *
 * Different ATS editors accept different markup — some only support plain
 * text, some require `<strong>` for bold, others require `<b>`, etc.
 * Adapters declare their formatting needs here and the shared script
 * uses the config to compose notes correctly.
 */
export type FormattingConfig = {
  /** "html" for rich-text editors, "plaintext" for textarea-based editors. */
  mode: "html" | "plaintext";
};

/** FormattingConfig with all defaults resolved — passed to adapter transform hooks. */
export type ResolvedFormattingConfig = {
  mode: "html" | "plaintext";
};

const resolveFormatting = (
  cfg?: FormattingConfig,
): ResolvedFormattingConfig => ({
  mode: cfg?.mode ?? "html",
});

/**
 * Minimal field shape that each ATS adapter must return.
 * The `text` is sent to the AI as-is; `transformedText` is used for matching
 * the AI response back to the correct field.
 */
export type ScorecardV3Field = {
  text: string;
  transformedText: string;
  editor: HTMLElement | null;
};

/**
 * Platform-specific adapter that each ATS implements.
 * Keeps DOM interaction isolated from the shared message/state logic.
 */
export type ScorecardV3Adapter = {
  /** Scrape the visible scorecard fields from the page */
  getScorecardFields: () => ScorecardV3Field[] | Promise<ScorecardV3Field[]>;

  /** Normalize text for fuzzy matching (strip whitespace, punctuation, etc.) */
  transformText: (text: string) => string;

  /**
   * Insert the UI element into the page.
   * Called on every render — the previous `.bh-scorecard-ui` is already removed.
   */
  insertUI: (uiContainer: HTMLElement) => void | Promise<void>;

  /** Write a note into an editor element (appends to existing content) */
  addNotesToField: (editor: HTMLElement, note: string) => void;

  /**
   * When true, the V3 UI is shown but autofill uses the legacy notes-matching
   * flow (V2 pipeline) instead of the AI-powered V3 mutation. The "additional
   * summary" toggle is hidden and clicking "Autofill scorecard" triggers a
   * `pullScorecard` message that causes the sidepanel to re-send the V2
   * `fillScorecard` message with matched notes.
   *
   * This is used when the `autofill-scorecard:v3` feature flag is off but
   * the ATS page uses an editor type that requires the V3 UI (e.g. the new
   * Greenhouse Quill-based scorecard layout).
   */
  legacyMode?: boolean;

  /**
   * Find the general/overall notes field (receives `overallSummary`).
   * Return `null` if there is no dedicated general notes area — the
   * first fillable field will be used as a fallback.
   */
  getGeneralNotesField?: () =>
    | ScorecardV3Field
    | null
    | Promise<ScorecardV3Field | null>;

  /**
   * Optional hook called on every `tabUrlChanged` or `tabTitleChanged` message.
   * Return `true` if the current page is a scorecard page and the UI
   * should be (re-)rendered; return `false` to remove the UI.
   */
  onTabUrlChanged?: () => boolean | Promise<boolean>;

  /**
   * Optional hook called once when the script initializes
   * (inside onDocumentLoaded). Use for one-time setup like
   * loading UI config or connecting mutation observers.
   */
  onInit?: () => void | Promise<void>;

  /**
   * Optional pre-render hook. Called before every render.
   * Use for platform-specific side effects like adding a "Clear all" button.
   */
  onBeforeRender?: () => void;

  /**
   * Formatting configuration for the target ATS editor.
   * Controls how the shared script composes notes (HTML vs plain text,
   * which bold tag to use, etc.). Defaults to `{ mode: "html" }`.
   */
  formatting?: FormattingConfig;

  /**
   * Optional hook for rendering a V3 structured question into HTML.
   * Called per-question when `structuredQuestions` is present in the response.
   * The shared script handles field matching and insertion — the adapter
   * only needs to render the structured bullets/citations into an HTML string.
   */
  transformStructuredQuestion?: (
    item: ScorecardQuestionStructured,
    callId: string,
    formatting: ResolvedFormattingConfig,
  ) => string | Promise<string>;

  /**
   * Optional hook for rendering V3 overall summary sections into HTML.
   * Called when `overallSummarySections` is present in the response.
   * The shared script handles getting the general notes field and insertion.
   */
  transformStructuredSummary?: (
    sections: ScorecardSummarySection[],
    callId: string,
    formatting: ResolvedFormattingConfig,
  ) => string | Promise<string>;

  /**
   * Optional hook for rendering custom template markdown summary into HTML.
   * Called when `customTemplateSummaryMarkdown` is present in the response.
   * TODO: We are assuming custom templates are in a markdown format, which might not be the case (see https://github.com/brighthire/brighthire/blob/88296485a92d2be8357e173fb0ea08958335a724/backend/python/app/brighthire/utils/custom_templates/run_custom_prompt_v2.py#L149)
   */
  transformMarkdownSummary?: (
    markdown: string,
    callId: string,
    formatting: ResolvedFormattingConfig,
  ) => string | Promise<string>;

  /**
   * Delay in ms between field insertions to avoid ATS auto-save race conditions.
   * Some ATSes (like Ashby) save each field individually but the mutation
   * re-renders the whole form, so rapid updates can cause fields to revert.
   * Defaults to 0 (no delay).
   */
  insertDelayMs?: number;

  /**
   * Optional hook to provide ATS-specific tooltip text for the
   * "Include additional summary" info icon.
   * Receives whether the org has custom templates and returns the tooltip string.
   * Falls back to generic copy if not provided.
   */
  getTooltipText?: (hasCustomTemplates: boolean) => string;

  /**
   * Optional URL for an ATS-specific "Learn more" help article link
   * shown next to the scorecard autofill title.
   */
  learnMoreUrl?: string;

  /**
   * If true, forces the narrow/vertical layout regardless of container width.
   * This moves the autofill button to the bottom of the UI instead of inline
   * with the header. Useful for ATSes where the UI container is always narrow.
   */
  forceNarrowLayout?: boolean;

  /**
   * Optional hook that returns an arbitrary key-value object forwarded
   * verbatim to the backend telemetry event (Datastore `telemetry_metadata`
   * field). Called once per autofill attempt, just before the
   * `fillScorecardV3Start` message is sent. Use to capture page-variant or
   * ATS-specific context without requiring a schema change.
   */
  getTelemetryMetadata?: () => Record<string, unknown>;
};

type RenderOptions = {
  autofillInProgress?: boolean;
  disabled?: boolean;
  shine?: boolean;
};

/**
 * Creates a V3 scorecard content script from a platform-specific adapter.
 *
 * Returns a `start` function that registers the message listener and
 * returns it (for cleanup by version routers).
 *
 * Usage:
 * ```ts
 * const { start } = createScorecardV3Script({ ...adapter });
 * export const myAtsStartV3 = start;
 * ```
 */
export const createScorecardV3Script = (adapter: ScorecardV3Adapter) => {
  let interviewData: FillScorecardV3CallDetails | null = null;
  let isDrawerLoading = true; // Assume drawer is loading initially
  // True after setToastText("View recording") arrives before loadingComplete,
  // meaning a match was found and fillScorecardV3Ready is on its way.
  // Prevents loadingComplete from flashing "No call selected" in that gap.
  let interviewMatchPending = false;
  let renderGeneration = 0;
  let autofillOptions: AutofillOptions = {
    includeAdditionalSummary: true,
    selectedTemplateId: null,
    overallSummaryStyle: BH_SUMMARY_STYLE_TOPIC,
    detailLevel: "MEDIUM",
  };
  let summaryTemplates: AutofillSummaryTemplate[] = [];
  let hasBeenAutofilled = false;
  /**
   * The autofill options that were active when the scorecard was last filled.
   * Used to determine whether the modal should show on the next autofill attempt.
   */
  let lastFilledOptions: AutofillOptions | null = null;
  // Used in legacy mode to gate `fillScorecard` handling to only the round-trip
  // that was triggered by the user clicking "Autofill scorecard".
  let legacyAutofillPending = false;
  const scorecardAutofillUiDisabledPromise = featureFlagEnabled(
    SCORECARD_AUTOFILL_UI_DISABLED_FEATURE,
  );

  const render = async (opts?: RenderOptions): Promise<void> => {
    const thisGeneration = ++renderGeneration;

    if (await scorecardAutofillUiDisabledPromise) {
      document.querySelectorAll(".bh-scorecard-ui").forEach((el) => {
        el.remove();
      });
      return;
    }

    adapter.onBeforeRender?.();

    // Capture current state at render start to detect changes during async insertUI
    const renderedInterviewData = interviewData;
    const renderedIsDrawerLoading = isDrawerLoading;

    // Show loading spinner if drawer is loading and we don't have interview data yet
    const showLoading =
      renderedIsDrawerLoading && renderedInterviewData === null;

    const uiContainer = createScorecardUI({
      autofillInProgress: opts?.autofillInProgress,
      autofillDisabled: opts?.disabled,
      showButtonShine: opts?.shine,
      loading: showLoading,
      interviewData,
      autofillOptions,
      summaryTemplates,
      legacyMode: adapter.legacyMode,
      getTooltipText: adapter.getTooltipText,
      learnMoreUrl: adapter.learnMoreUrl,
      forceNarrowLayout: adapter.forceNarrowLayout,
      onImportAll: (e) => {
        onImportAll(e);
      },
      onSelectInterview: () => {
        sendMessageWithTabId({ action: "openDrawer" });
      },
      onAutofillOptionsChange: (newOptions) => {
        autofillOptions = newOptions;
        render(opts);
      },
    });

    // If a newer render was kicked off, abandon this one.
    if (thisGeneration !== renderGeneration) return;

    document.querySelectorAll(".bh-scorecard-ui").forEach((el) => {
      el.remove();
    });
    await adapter.insertUI(uiContainer);

    // If a newer render started while insertUI was awaiting,
    // remove what we just inserted — the newer render owns the UI.
    if (thisGeneration !== renderGeneration) {
      uiContainer.remove();
      return;
    }

    // If state changed during insertUI, re-render with new state. This handles
    // race conditions where data arrived or loading completed during insertion.
    if (
      interviewData !== renderedInterviewData ||
      isDrawerLoading !== renderedIsDrawerLoading
    ) {
      const { transcriptLoading, autofillUnavailable } = interviewData ?? {};
      render({
        disabled:
          transcriptLoading || autofillUnavailable || interviewData === null,
      });
    }
  };

  const executeAutofill = async (
    e: MouseEvent,
    forceRegenerate = false,
  ): Promise<void> => {
    if (adapter.legacyMode) {
      // Legacy mode: trigger the notes-matching pipeline in the sidepanel.
      // The sidepanel's `useLegacyFallbackNotes` hook listens for
      // `pullScorecard` and responds with a `fillScorecard` message carrying
      // notes matched by question label. We handle that response
      // in the `fillScorecard` branch of the message listener below.
      legacyAutofillPending = true;
      render({ autofillInProgress: true });
      sendMessageWithTabId({ action: "pullScorecard" });
      sendMessageWithTabId({
        action: "scorecardFilled",
        payload: {
          gaEvent: {
            eventLabel: e.isTrusted ? "manual_import_all" : "auto_import_all",
          },
        },
      });
      return;
    }

    render({ autofillInProgress: true });

    // Retry scraping scorecard fields with backoff if the DOM hasn't rendered
    // them yet. Greenhouse's React app can lag behind the content script,
    // resulting in 0 fields on the first attempt.
    const FIELD_RETRY_DELAYS = [150, 300];
    let scorecardFields = await adapter.getScorecardFields();
    for (
      let i = 0;
      i < FIELD_RETRY_DELAYS.length && scorecardFields.length === 0;
      i++
    ) {
      await new Promise((r) => setTimeout(r, FIELD_RETRY_DELAYS[i]));
      scorecardFields = await adapter.getScorecardFields();
    }
    // Snapshot the options being submitted so the modal can compare them later.
    lastFilledOptions = { ...autofillOptions };
    const adapterMetadata = adapter.getTelemetryMetadata?.();
    const telemetryMetadata: Record<string, unknown> = {
      extension_version: chrome.runtime.getManifest().version,
      scraped_questions: scorecardFields.map((field) => field.text),
      tab_url: window.location.href,
      ...adapterMetadata,
    };
    sendMessageWithTabId({
      action: "fillScorecardV3Start",
      payload: {
        scorecardDataV3: {
          questions: scorecardFields.map((field) => field.text),
          autofillOptions: { ...autofillOptions, forceRegenerate },
          telemetryMetadata,
        },
      },
    });
    sendMessageWithTabId({
      action: "scorecardFilled",
      payload: {
        gaEvent: {
          eventLabel: e.isTrusted ? "manual_import_all" : "auto_import_all",
        },
      },
    });
  };

  /**
   * Returns true if all autofill settings are identical to the last fill.
   * Only an exact match warrants the "overwrite" modal and forceRegenerate=true.
   * Any change (template, style, detail level, or additional summary toggle)
   * means the cache will produce a different result, so no warning is needed.
   */
  const settingsMatchLastFill = (): boolean => {
    if (!lastFilledOptions) return false;
    return (
      autofillOptions.selectedTemplateId ===
        lastFilledOptions.selectedTemplateId &&
      autofillOptions.overallSummaryStyle ===
        lastFilledOptions.overallSummaryStyle &&
      autofillOptions.detailLevel === lastFilledOptions.detailLevel &&
      autofillOptions.includeAdditionalSummary ===
        lastFilledOptions.includeAdditionalSummary
    );
  };

  const onImportAll = (e: MouseEvent): void => {
    if (hasBeenAutofilled && settingsMatchLastFill()) {
      const modal = createConfirmAutofillModal({
        onConfirm: () => executeAutofill(e, true),
        onCancel: () => {},
      });
      document.body.appendChild(modal);
      return;
    }
    executeAutofill(e);
  };

  const insertNotes = async ({
    overallSummarySections,
    structuredQuestions,
    callId,
    customTemplateSummaryMarkdown,
    personalQuestionNotes,
    generalPersonalNotes,
    hideAiHeaders,
  }: FillScorecardV3ResponsePayload): Promise<void> => {
    const fmt = resolveFormatting(adapter.formatting);
    const html = fmt.mode === "html";
    const INTERVIEWER_NOTES_HEADER = "Notes from interviewer:";
    const AI_NOTES_HEADER = hideAiHeaders
      ? "Summarized notes:"
      : "✨ AI summarized notes:";
    const BREAK = html ? "<p><br></p>" : "\n\n";

    const fields = await adapter.getScorecardFields();
    const fieldMap = new Map(
      fields.map((field) => [field.transformedText, field]),
    );

    // Build personal notes lookup by transformed question text.
    const personalNotesMap = new Map<string, ScorecardBullet[]>(
      (personalQuestionNotes ?? []).map((pn) => [
        adapter.transformText(pn.questionText),
        pn.bullets,
      ]),
    );
    const consumedPersonalKeys = new Set<string>();

    // Per-question notes
    if (callId && structuredQuestions && adapter.transformStructuredQuestion) {
      for (const item of structuredQuestions) {
        const transformedQ = adapter.transformText(item.question);
        const field = fieldMap.get(transformedQ);
        if (!field?.editor) continue;

        const personalBullets = personalNotesMap.get(transformedQ);
        if (personalBullets) consumedPersonalKeys.add(transformedQ);

        const hasAiBullets = item.bullets && item.bullets.length > 0;
        const hasPersonalBullets =
          personalBullets && personalBullets.length > 0;

        const personalText = hasPersonalBullets
          ? await adapter.transformStructuredQuestion(
              {
                question: item.question,
                bullets: personalBullets,
                reasonIfUnanswered: null,
              },
              callId,
              fmt,
            )
          : "";

        const aiText = hasAiBullets
          ? await adapter.transformStructuredQuestion(item, callId, fmt)
          : "";

        let composedNote: string;
        if (personalText && aiText) {
          const personalHeader = html
            ? `<p><strong>${INTERVIEWER_NOTES_HEADER}</strong></p>`
            : INTERVIEWER_NOTES_HEADER;
          const aiHeader = html
            ? `<p><strong>${AI_NOTES_HEADER}</strong></p>`
            : AI_NOTES_HEADER;
          composedNote = `${personalHeader}${BREAK}${personalText}${BREAK}${aiHeader}${BREAK}${aiText}`;
        } else if (personalText) {
          composedNote = personalText;
        } else if (aiText) {
          composedNote = aiText;
        } else {
          continue;
        }

        adapter.addNotesToField(field.editor, composedNote);

        // Delay between field insertions to avoid ATS auto-save race conditions.
        if (adapter.insertDelayMs && adapter.insertDelayMs > 0) {
          await new Promise((resolve) => {
            setTimeout(resolve, adapter.insertDelayMs);
          });
        }
      }
    }

    // Helper to resolve the general notes field from the DOM.
    const resolveGeneralField = ():
      | Promise<ScorecardV3Field | null>
      | ScorecardV3Field
      | null =>
      adapter.getGeneralNotesField
        ? adapter.getGeneralNotesField()
        : (fields.find((f) => f.editor) ?? null);

    // General / Key Takeaways: build one payload and insert once.
    const generalParts: string[] = [];

    // Unmatched per-question personal notes + general personal notes,
    // all rendered via transformStructuredSummary as a single section.
    const unmatchedBullets: ScorecardBullet[] = [];
    if (generalPersonalNotes && generalPersonalNotes.length > 0) {
      unmatchedBullets.push(...generalPersonalNotes);
    }
    personalNotesMap.forEach((bullets, key) => {
      if (!consumedPersonalKeys.has(key)) {
        unmatchedBullets.push(...bullets);
      }
    });
    if (
      callId &&
      unmatchedBullets.length > 0 &&
      adapter.transformStructuredSummary
    ) {
      const personalSection = [
        { header: INTERVIEWER_NOTES_HEADER, bullets: unmatchedBullets },
      ];
      const note = await adapter.transformStructuredSummary(
        personalSection,
        callId,
        fmt,
      );
      if (note) generalParts.push(note);
    }

    if (
      callId &&
      overallSummarySections &&
      adapter.transformStructuredSummary
    ) {
      const note = await adapter.transformStructuredSummary(
        overallSummarySections,
        callId,
        fmt,
      );
      if (note) generalParts.push(note);
    }

    // Custom template markdown overrides the structured summary when present
    if (
      callId &&
      customTemplateSummaryMarkdown &&
      adapter.transformMarkdownSummary
    ) {
      const note = await adapter.transformMarkdownSummary(
        customTemplateSummaryMarkdown,
        callId,
        fmt,
      );
      if (note) generalParts.push(note);
    }

    const mergedGeneral = generalParts.join(BREAK);
    if (mergedGeneral) {
      const generalField = await resolveGeneralField();
      if (generalField?.editor) {
        adapter.addNotesToField(generalField.editor, mergedGeneral);
      }
    }
  };

  /**
   * Converts a legacy V2 `<br>`-separated HTML string into `<p>`-wrapped
   * paragraphs matching V3 output format.
   *
   * V2 notes look like:
   *   Notes from interviewer:<br><br>
   *   •&nbsp;&nbsp;⭐&nbsp;&nbsp;note text&nbsp;&nbsp;<a>1:12</a><br>
   *   •&nbsp;&nbsp;note text
   *
   * This converts each line to a <p> and normalizes the double-&nbsp;
   * separators between bullet/emoji/text/timestamp down to single ones.
   */
  const legacyNotesToHtml = (text: string): string => {
    const fmt = resolveFormatting(adapter.formatting);
    if (fmt.mode !== "html") return text;
    return text
      .split(/<br\s*\/?>/gi)
      .map((s) =>
        s
          // Collapse runs of &nbsp; / \u00a0 / spaces down to a single \u00a0
          .replace(/(\s|&nbsp;|\u00a0){2,}/gi, "\u00a0")
          .trim(),
      )
      .filter((s) => s.length > 0)
      .map((s) => {
        // Already block-level HTML — pass through unwrapped
        if (/^<p[\s>]/i.test(s)) return s;
        // Plain header lines (no bullet, no tag, ends with ":") → bold
        const isHeader = /^[^<•\u2022]+:$/.test(s);
        return isHeader ? `<p><strong>${s}</strong></p>` : `<p>${s}</p>`;
      })
      .join("");
  };

  /**
   * Legacy mode only: insert V2-formatted notes (`FillScorecardPayload`) into
   * the ATS scorecard fields. Matches each `questionNotes` entry to its field
   * by comparing normalized label text, then appends using `addNotesToField`.
   * General / unmatched notes are written to the general notes field.
   */
  const insertLegacyNotes = async (
    scorecardData: FillScorecardPayload,
  ): Promise<void> => {
    const fmt = resolveFormatting(adapter.formatting);
    const BREAK = fmt.mode === "html" ? "<p><br></p>" : "\n\n";

    const fields = await adapter.getScorecardFields();
    const fieldMap = new Map(
      fields.map((f) => [adapter.transformText(f.text), f]),
    );

    const unmatchedNotes: string[] = [];

    for (const question of scorecardData.questionNotes) {
      if (question.notes.count === 0) continue;
      const key = adapter.transformText(question.text);
      const field = fieldMap.get(key);
      if (field?.editor) {
        adapter.addNotesToField(
          field.editor,
          legacyNotesToHtml(question.notes.text),
        );
      } else {
        // Could not match to a scorecard field — fall back to general notes
        unmatchedNotes.push(legacyNotesToHtml(question.notes.text));
      }
    }

    // Write general notes + any unmatched question notes to the general field
    const generalParts: string[] = [];
    if (scorecardData.generalNotes.count > 0) {
      generalParts.push(legacyNotesToHtml(scorecardData.generalNotes.text));
    }
    generalParts.push(...unmatchedNotes);

    if (generalParts.length > 0) {
      const generalField = adapter.getGeneralNotesField
        ? await adapter.getGeneralNotesField()
        : (fields.find((f) => f.editor) ?? null);
      if (generalField?.editor) {
        adapter.addNotesToField(generalField.editor, generalParts.join(BREAK));
      }
    }

    hasBeenAutofilled = true;
    render({ shine: false });
    showConfetti();
  };

  const addListener = (): MessageListener => {
    render({ disabled: true });

    const listener: MessageListener = ({ message }) => {
      if (
        (message.action === "tabUrlChanged" ||
          message.action === "tabTitleChanged") &&
        adapter.onTabUrlChanged
      ) {
        const result = adapter.onTabUrlChanged();
        const isUrlChange = message.action === "tabUrlChanged";

        const handle = (isScorecardPage: boolean): void => {
          if (isScorecardPage) {
            if (isUrlChange) {
              // URL changed: clear stale data and reset pending flag so the
              // drawer can signal a fresh match for the new page.
              interviewData = null;
              interviewMatchPending = false;
              render({ disabled: true });
            } else if (
              interviewData === null ||
              !document.querySelector(".bh-scorecard-ui")
            ) {
              // tabTitleChanged with no interview data yet, or the UI is missing
              // from the DOM (e.g. a previous insertUI failed because the page
              // was still loading when it ran — common on slow direct URL loads
              // like Ashby tab view where #content exists but its children haven't
              // rendered yet). Trigger a render without clearing existing data so
              // fillScorecardV3Ready state is preserved.
              render({
                disabled:
                  interviewData === null ||
                  !!interviewData?.transcriptLoading ||
                  !!interviewData?.autofillUnavailable,
              });
            }
            // tabTitleChanged with interviewData set and UI in the DOM: the URL
            // hasn't changed so don't clear it — the drawer won't resend
            // fillScorecardV3Ready.
          } else {
            document.querySelectorAll(".bh-scorecard-ui").forEach((el) => {
              el.remove();
            });
            interviewData = null;
            interviewMatchPending = false;
            hasBeenAutofilled = false;
            legacyAutofillPending = false;
            clearAlert();
          }
        };

        if (result instanceof Promise) {
          result.then(handle);
        } else {
          handle(result);
        }
      }

      if (message.action === "drawerLoading") {
        isDrawerLoading = true;
        interviewMatchPending = false;
        render({ disabled: true });
      } else if (message.action === "loadingComplete") {
        if (interviewMatchPending) {
          if (adapter.legacyMode) {
            // In legacy mode the sidepanel doesn't send fillScorecardV3Ready,
            // so we won't receive call details for display. Treat the match
            // signal from setToastText as sufficient to enable the button.
            // Use a minimal interviewData stub so the UI shows as "ready".
            interviewMatchPending = false;
            isDrawerLoading = false;
            if (!interviewData) {
              interviewData = {};
            }
            render({ disabled: false });
          } else {
            // setToastText("View recording") already arrived, meaning the drawer
            // found a match and fillScorecardV3Ready is incoming. Keep the
            // spinner rather than flashing "No call selected".
            isDrawerLoading = true;
          }
        } else {
          isDrawerLoading = false;
          render({ disabled: interviewData === null });
        }
      } else if (
        message.action === "setToastText" &&
        message.payload?.text === "View recording" &&
        isDrawerLoading
      ) {
        // A match was found — fillScorecardV3Ready is on its way (or in legacy
        // mode, loadingComplete will use this flag to enable the button).
        // Only set the flag while the drawer is still loading to avoid
        // treating a later "View recording" (e.g. from ScorecardExtensionViewV3
        // on re-render) as a pending signal.
        interviewMatchPending = true;
      } else if (
        message.action === "setToastText" &&
        (message.payload?.text === "Pick recording" ||
          message.payload?.text === "No recordings")
      ) {
        interviewMatchPending = false;
        interviewData = null;
        isDrawerLoading = false;
        render({ disabled: true });
      } else if (
        message.action === "fillScorecardV3Ready" &&
        message.payload?.callDetails
      ) {
        interviewMatchPending = false;
        isDrawerLoading = false;
        interviewData = message.payload.callDetails;
        if (interviewData.hasBeenAutofilled) {
          hasBeenAutofilled = true;
          // For auto-drafted scorecards, treat the saved settings as the
          // last-filled options so the modal comparison works correctly.
          if (!lastFilledOptions && message.payload.savedAutofillSettings) {
            const s = message.payload.savedAutofillSettings;
            lastFilledOptions = {
              includeAdditionalSummary: s.includeAdditionalSummary,
              selectedTemplateId: s.selectedTemplateId,
              overallSummaryStyle: s.overallSummaryStyle,
              detailLevel: s.detailLevel,
            };
          }
        }
        const saved = message.payload.savedAutofillSettings;
        if (message.payload.summaryTemplates) {
          summaryTemplates = message.payload.summaryTemplates;
        }

        // Interview-level default template always takes precedence over the
        // user's saved template — it reflects the most relevant template for
        // this specific call (meeting type, keywords, persona, org default).
        const interviewDefaultTemplate = summaryTemplates.find(
          (t) => t.isDefault,
        );

        autofillOptions = {
          ...autofillOptions,
          ...saved,
          // Interview default always wins for template; saved is the fallback
          selectedTemplateId:
            interviewDefaultTemplate?.id ?? saved?.selectedTemplateId ?? null,
        };
        const { transcriptLoading, autofillUnavailable } = interviewData;
        render({ disabled: transcriptLoading || autofillUnavailable });
      } else if (message.action === "fillScorecardV3Response") {
        render({ shine: false });
        if (message.payload?.scorecardDataV3Response) {
          hasBeenAutofilled = true;
          // Confirm the snapshot — lastFilledOptions was already set in
          // executeAutofill but this ensures it's set even if the snapshot
          // was somehow missed.
          if (!lastFilledOptions) {
            lastFilledOptions = { ...autofillOptions };
          }
          insertNotes(message.payload.scorecardDataV3Response).then(() => {
            showConfetti();
          });
        }
      } else if (message.action === "getScorecardItems" && adapter.legacyMode) {
        // Legacy mode: the sidepanel needs the ATS scorecard field labels so
        // the backend can match AI notes to the correct questions.
        const fieldsOrPromise = adapter.getScorecardFields();
        const buildItems = (fields: ScorecardV3Field[]): MessageResponse => ({
          scorecardItems: fields.map((f) => ({
            key: f.transformedText,
            text: f.text,
          })),
        });

        if (fieldsOrPromise instanceof Promise) {
          return fieldsOrPromise.then(buildItems);
        }
        return buildItems(fieldsOrPromise);
      } else if (
        message.action === "fillScorecard" &&
        adapter.legacyMode &&
        legacyAutofillPending &&
        message.payload?.scorecardData &&
        !message.payload.isLoading
      ) {
        // Legacy mode: the sidepanel's useLegacyFallbackNotes responded to
        // our `pullScorecard` with matched notes. Insert them into the
        // correct fields using the ATS adapter's field-writing helpers.
        legacyAutofillPending = false;
        insertLegacyNotes(message.payload.scorecardData);
      } else if (message.action === "clearAlert") {
        clearAlert();
        // Reset all state
        interviewData = null;
        interviewMatchPending = false;
        hasBeenAutofilled = false;
        lastFilledOptions = null;
        legacyAutofillPending = false;
        render({ disabled: true });
      } else if (message.action === "showAlert" && message.payload?.alert) {
        showAlert(message.payload.alert);
      } else if (message.action === "showFeedback") {
        showFeedback();
      }
    };

    addMessageListener(listener);
    return listener;
  };

  const start = (): MessageListener => {
    adapter.onInit?.();
    return addListener();
  };

  return { start, render };
};
